const CATEGORIES = ['All', 'burgers', 'buckets', 'chicken', 'snacks', 'drinks'];

const Menu = () => {
  const [activeCat, setActiveCat] = useState('All');
  const [search, setSearch] = useState('');

  const filtered = MENU_ITEMS.filter(item => {
    const matchesCat = activeCat === 'All' || item.category === activeCat;
    const matchesSearch = item.name.toLowerCase().includes(search.toLowerCase());
    return matchesCat && matchesSearch;
  });

  return (
    <div className="pb-24 pt-4 px-4 h-screen flex flex-col">
      <h1 className="text-2xl font-bold mb-4">Menu</h1>

      {/* Search */}
      <div className="relative mb-4">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
        <input 
          type="text" 
          placeholder="Search for crispy chicken..." 
          className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl text-sm outline-none focus:border-red-500 focus:ring-1 focus:ring-red-500"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      {/* Filter Chips */}
      <div className="flex space-x-2 overflow-x-auto hide-scrollbar mb-6 flex-shrink-0">
        {CATEGORIES.map(cat => (
            <button
                key={cat}
                onClick={() => setActiveCat(cat)}
                className={`px-4 py-2 rounded-full text-xs font-bold capitalize whitespace-nowrap transition-colors ${
                    activeCat === cat 
                    ? 'bg-red-600 text-white shadow-md shadow-red-200' 
                    : 'bg-white text-slate-600 border border-slate-200'
                }`}
            >
                {cat}
            </button>
        ))}
      </div>

      {/* Grid */}
      <div className="grid grid-cols-2 gap-4 overflow-y-auto pb-20">
        {filtered.map(item => (
            <ProductCard key={item.id} product={item} />
