import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Mic, MicOff, Loader2, Volume2 } from 'lucide-react';
import { GoogleGenAI, LiveServerMessage, Modality, FunctionDeclaration, Type } from '@google/genai';
import { useCart } from '../context/CartContext';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { MENU_ITEMS, SYSTEM_INSTRUCTION } from '../constants';
import { createBlob, decode, decodeAudioData } from '../utils/audio';

// --- Tool Definitions ---

const addToOrderDecl: FunctionDeclaration = {
  name: 'addToOrder',
  description: 'Add an item to the cart using its exact menu name.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      itemName: { type: Type.STRING, description: 'The exact name of the product from the menu.' },
      quantity: { type: Type.NUMBER, description: 'Quantity to add.' }
    },
    required: ['itemName', 'quantity']
  }
};

const getCartStatusDecl: FunctionDeclaration = {
  name: 'getCartStatus',
  description: 'Get the current list of items in the cart and the total price.',
  parameters: {
    type: Type.OBJECT,
    properties: {}
  }
};

const confirmOrderDecl: FunctionDeclaration = {
  name: 'confirmOrder',
  description: 'Confirm the order and go to checkout.',
  parameters: {
    type: Type.OBJECT,
    properties: {}
  }
};

const LiveAgent: React.FC = () => {
  const [active, setActive] = useState(false);
  const [connecting, setConnecting] = useState(false);
  const [speaking, setSpeaking] = useState(false);

  const { addToCart, items, total } = useCart();
  const navigate = useNavigate();

  // Refs for audio context and session
  const audioContextRef = useRef<AudioContext | null>(null);
  const inputContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<any>(null); // To store session object
  const streamRef = useRef<MediaStream | null>(null);

  // Helper to find product (fuzzy match simulation or strict)
  const findProduct = (name: string) => {
    return MENU_ITEMS.find(p => p.name.toLowerCase().includes(name.toLowerCase()));
  };

  const stopAudio = useCallback(() => {
    if (audioContextRef.current) {
        audioContextRef.current.suspend();
    }
    sourcesRef.current.forEach(source => {
        try { source.stop(); } catch(e) {}
    });
    sourcesRef.current.clear();
    setSpeaking(false);
  }, []);

  const disconnect = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (inputContextRef.current) {
        inputContextRef.current.close();
        inputContextRef.current = null;
    }
    if (audioContextRef.current) {
        audioContextRef.current.close();
        audioContextRef.current = null;
    }
    setActive(false);
    setConnecting(false);
    setSpeaking(false);
  }, []);

  const connect = useCallback(async () => {
    if (!process.env.API_KEY) {
      alert("API Key missing");
      return;
    }

    try {
      setConnecting(true);

      // 1. Audio Setup
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const inputContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      inputContextRef.current = inputContext;

      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = audioContext;
      nextStartTimeRef.current = 0;

      // 2. Initialize Client
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction: SYSTEM_INSTRUCTION,
          tools: [{ functionDeclarations: [addToOrderDecl, getCartStatusDecl, confirmOrderDecl] }],
          speechConfig: {
              voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          }
        },
        callbacks: {
          onopen: () => {
            console.log('Gemini Live Connected');
            setConnecting(false);
            setActive(true);

            // Start Audio Stream Input
            const source = inputContext.createMediaStreamSource(stream);
            const scriptProcessor = inputContext.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(session => {
                  session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(inputContext.destination);
          },
          onmessage: async (msg: LiveServerMessage) => {
            // Handle Audio Output
            const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) {
                setSpeaking(true);
                if (audioContext.state === 'suspended') await audioContext.resume();

                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, audioContext.currentTime);

                const audioBuffer = await decodeAudioData(
                    decode(audioData),
                    audioContext,
                    24000,
                    1
                );

                const source = audioContext.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(audioContext.destination);
                source.addEventListener('ended', () => {
                    sourcesRef.current.delete(source);
                    if(sourcesRef.current.size === 0) setSpeaking(false);
                });

                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += audioBuffer.duration;
                sourcesRef.current.add(source);
            }

            // Handle Interruption
            if (msg.serverContent?.interrupted) {
                stopAudio();
                nextStartTimeRef.current = 0;
            }

            // Handle Tool Calls
            if (msg.toolCall) {
                for (const fc of msg.toolCall.functionCalls) {
                    let result: any = { error: 'Unknown tool' };
                    console.log("Calling Tool:", fc.name, fc.args);

                    try {
                        if (fc.name === 'addToOrder') {
                            const { itemName, quantity } = fc.args as any;
                            const product = findProduct(itemName);
                            if (product) {
                                addToCart(product, Number(quantity));
                                result = { success: true, message: `Added ${quantity} ${product.name} to cart.` };
                            } else {
                                result = { success: false, message: `Product ${itemName} not found.` };
                            }
                        } else if (fc.name === 'getCartStatus') {
                            const currentTotal = localStorage.getItem('kfc_cart') ? JSON.parse(localStorage.getItem('kfc_cart')!).reduce((acc: number, item: any) => acc + (item.price * item.quantity), 0) : 0;
                            const currentCount = localStorage.getItem('kfc_cart') ? JSON.parse(localStorage.getItem('kfc_cart')!).length : 0;

                            result = { 
                                count: currentCount,
                                total: currentTotal,
                                currency: 'UZS'
                            };
                        } else if (fc.name === 'confirmOrder') {
                            navigate('/cart');
                            result = { success: true, message: "Navigating to checkout." };
                        }
                    } catch (e) {
                        result = { error: (e as Error).message };
                    }

                    // Send Tool Response
                    sessionPromise.then(session => {
                        session.sendToolResponse({
                            functionResponses: [{
                                id: fc.id,
                                name: fc.name,
                                response: { result }
                            }]
                        });
                    });
                }
            }
          },
          onclose: () => {
            console.log("Session closed");
            setActive(false);
          },
          onerror: (err) => {
            console.error("Gemini Error", err);
            setActive(false);
            setConnecting(false);
          }
        }
      });
      sessionRef.current = sessionPromise;

    } catch (e) {
      console.error(e);
      setConnecting(false);
    }
  }, [addToCart, navigate, stopAudio]);

  return (
    <div className="fixed bottom-20 right-4 z-50">
      <button
        onClick={active ? disconnect : connect}
        className={`w-16 h-16 rounded-full shadow-xl flex items-center justify-center transition-all duration-300 ${
          active 
            ? 'bg-white text-red-600 border-2 border-red-600 animate-pulse' 
            : 'bg-red-600 text-white hover:bg-red-700 hover:scale-105'
        }`}
      >
        {connecting ? (
          <Loader2 className="animate-spin" />
        ) : active ? (
          speaking ? <Volume2 className="animate-bounce" /> : <Mic />
        ) : (
          <MicOff />
        )}
      </button>
      {active && (
        <div className="absolute bottom-20 right-0 bg-black/80 text-white text-xs px-3 py-1 rounded-lg whitespace-nowrap mb-2">
          KFC Assistant Active
        </div>
      )}
    </div>
  );
};

export default LiveAgent;

