      <div className="px-4 pb-2 bg-slate-50 z-10">
        <h1 className="text-2xl font-black uppercase tracking-tighter text-slate-900 mb-3">{t.menu}</h1>

        {/* Search */}
        <div className="flex gap-2 mb-4">
            <div className="relative flex-grow">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                type="text" 
                placeholder={t.searchPlaceholder}
                className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl text-sm outline-none focus:border-red-600 focus:ring-1 focus:ring-red-600 shadow-sm"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                />
            </div>
            <button className="bg-white px-3 rounded-xl border border-slate-200 text-slate-600 shadow-sm">
                <SlidersHorizontal size={18} />
            </button>
        </div>

        {/* Filter Chips - Sticky */}
        <div className="flex space-x-2 overflow-x-auto hide-scrollbar pb-1">
            {CATEGORIES.map(cat => (
                <button
                    key={cat}
                    onClick={() => setActiveCat(cat)}
                    className={`px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wide whitespace-nowrap transition-all border ${
