            <input 
                type="tel" 
                placeholder="+998..." 
                className="w-full p-3 border rounded-xl"
                value={phone}
                onChange={e => setPhone(e.target.value)}
            />
            <button 
                onClick={() => login(phone || '+998901234567')}
                className="w-full bg-red-600 text-white py-3 rounded-xl font-bold"
            >
                {t.login}
            </button>
            <p className="text-xs text-slate-400 mt-4 text-center">
                Demo Admin Access: Enter <span className="font-mono text-slate-600">+998901234567</span>
            </p>
        </div>
    )
  }

  return (
    <div className="p-6 pt-10">
        <h1 className="text-3xl font-bold mb-2">Hello, {user.name}</h1>
        <p className="text-slate-500 mb-8">{user.phone}</p>

        {isAdmin && (
            <button 
                onClick={() => navigate('/admin')}
                className="w-full bg-slate-900 text-white py-4 rounded-xl font-bold flex items-center justify-center gap-2 mb-6 shadow-lg shadow-slate-200"
            >
                <LayoutDashboard size={20} /> Open Admin Panel
            </button>
        )}

        <div className="bg-white rounded-2xl p-4 shadow-sm mb-4">
            <h2 className="font-bold mb-4">{t.settings}</h2>
            <div className="space-y-4">
                <div className="flex justify-between py-2 border-b border-slate-50">
                    <span>{t.notification}</span>
                    <span className="text-red-600 font-bold">On</span>
                </div>
                <div className="py-2 border-b border-slate-50">
                    <div className="flex justify-between mb-2">
                        <span>{t.language}</span>
                    </div>
                    <div className="flex bg-slate-100 p-1 rounded-lg">
                        {(['uz', 'ru', 'en'] as const).map((l) => (
                            <button
                                key={l}
                                onClick={() => setLang(l)}
                                className={`flex-1 py-1 rounded-md text-sm font-bold transition-all ${
                                    lang === l ? 'bg-white text-red-600 shadow-sm' : 'text-slate-400'
                                }`}
                            >
                                {l.toUpperCase()}
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>

        <button onClick={logout} className="w-full py-3 text-red-600 font-bold bg-red-50 rounded-xl">
            {t.logout}
        </button>
    </div>
  );
};

export default Profile;

import React from 'react';
import { useCart } from '../context/CartContext';
import { useOrders } from '../context/OrderContext';
import { useAuth } from '../context/AuthContext';
import { Minus, Plus, Trash2, CheckCircle } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { formatCurrency } from '../utils/format';

const Cart = () => {
  const { items, updateQuantity, removeFromCart, total, clearCart } = useCart();
  const { placeOrder } = useOrders();
  const { user, currentAddress } = useAuth();
  const navigate = useNavigate();
  const { t } = useLanguage();
  const [success, setSuccess] = React.useState(false);

  const handleCheckout = () => {
    if (!user) {
        navigate('/profile'); // prompt login
        return;
    }

    placeOrder(
        items, 
        total, 
        currentAddress, 
        user.phone
    );

    clearCart();
    setSuccess(true);
    setTimeout(() => {
        setSuccess(false);
        navigate('/');
    }, 2000);
  };

  if (success) {
      return (
          <div className="h-screen flex flex-col items-center justify-center bg-white p-6 text-center animate-slide-up">
              <CheckCircle className="text-green-500 w-24 h-24 mb-4" />
              <h1 className="text-3xl font-black text-slate-900 mb-2">Order Placed!</h1>
              <p className="text-slate-500">Your chicken is being prepared.</p>
          </div>
      )
  }

  if (items.length === 0) {
    return (
        <div className="flex flex-col items-center justify-center h-screen pb-20 px-4">
            <div className="w-24 h-24 bg-red-50 rounded-full flex items-center justify-center mb-4 text-red-500">
                <Trash2 size={40} />
            </div>
            <h2 className="text-xl font-bold text-slate-800 mb-2">{t.emptyCart}</h2>
            <p className="text-slate-500 text-center mb-6">{t.emptyCartDesc}</p>
            <button 
                onClick={() => navigate('/menu')}
                className="bg-red-600 text-white px-8 py-3 rounded-xl font-bold shadow-lg shadow-red-200"
            >
                {t.goToMenu}
            </button>
        </div>
    );
  }

  return (
    <div className="pb-32 pt-4 px-4 min-h-screen bg-slate-50">
      <h1 className="text-2xl font-bold mb-6">{t.cart}</h1>

      <div className="space-y-4">
        {items.map(item => (
            <div key={item.id} className="bg-white p-4 rounded-2xl flex items-center shadow-sm">
                <img src={item.image} alt={item.name} className="w-16 h-16 rounded-lg object-cover bg-slate-100" />
                <div className="ml-4 flex-grow">
                    <h3 className="font-bold text-slate-800 text-sm line-clamp-1">{item.name}</h3>
                    <p className="text-red-600 font-bold mt-1">{formatCurrency(item.price * item.quantity)}</p>
                </div>
                <div className="flex items-center space-x-3 bg-slate-50 rounded-lg p-1">
                    <button 
                        onClick={() => updateQuantity(item.id, -1)}
                        className="w-7 h-7 flex items-center justify-center bg-white rounded-md shadow-sm text-slate-600 active:scale-95 transition-transform"
                    >
                        <Minus size={14} />
                    </button>
                    <span className="text-sm font-bold w-4 text-center">{item.quantity}</span>
                    <button 
                        onClick={() => updateQuantity(item.id, 1)}
                        className="w-7 h-7 flex items-center justify-center bg-white rounded-md shadow-sm text-slate-600 active:scale-95 transition-transform"
                    >
                        <Plus size={14} />
                    </button>
                </div>
            </div>
        ))}
      </div>

      <div className="fixed bottom-20 left-4 right-4 bg-white p-5 rounded-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.05)] border border-slate-100">
        <div className="flex justify-between items-center mb-4 text-slate-600">
            <span>{t.subtotal}</span>
            <span>{formatCurrency(total)}</span>
        </div>
        <div className="flex justify-between items-center mb-6">
            <span className="font-bold text-lg text-slate-900">{t.total}</span>
            <span className="font-bold text-xl text-slate-900">{formatCurrency(total)}</span>
        </div>
        <button 
            className="w-full bg-red-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg shadow-red-200 active:scale-[0.98] transition-transform"
            onClick={handleCheckout}
        >
            {t.checkout}
        </button>
      </div>
    </div>
  );
};

export default Cart;

import React from 'react';
