  return (
    <div className="pb-20">
      <h2 className="text-2xl font-black text-slate-900 mb-4">Order Manager</h2>

      {orders.length === 0 ? (
        <div className="text-center py-20 opacity-50">
          <Clock size={48} className="mx-auto mb-4 text-slate-400" />
