          {/* Completed */}
          {orders.some(o => o.status === 'completed') && (
             <div>
               <h3 className="font-bold text-green-600 uppercase text-xs tracking-wider mb-2">History</h3>
               {orders.filter(o => o.status === 'completed').map(o => <OrderCard key={o.id} order={o} />)}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default AdminOrders;

import React, { useEffect, useRef, useState } from 'react';
import L from 'leaflet';
import { X, MapPin, Navigation, Loader2 } from 'lucide-react';
import { useLanguage } from '../context/LanguageContext';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (address: string) => void;
}

const AddressModal: React.FC<Props> = ({ isOpen, onClose, onConfirm }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<L.Map | null>(null);
  const { t } = useLanguage();
  const [loading, setLoading] = useState(false);
  const [currentAddress, setCurrentAddress] = useState(t.moveMap);
  const [canConfirm, setCanConfirm] = useState(false);

  // Initialize Map
  useEffect(() => {
    if (!isOpen || !mapContainerRef.current) return;

    // Default center (Tashkent)
    const defaultCenter: [number, number] = [41.311081, 69.240562];

    if (!mapInstanceRef.current) {
      const map = L.map(mapContainerRef.current, {
        center: defaultCenter,
        zoom: 15,
        zoomControl: false,
        attributionControl: false
      });

      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        maxZoom: 19,
        attribution: '© OpenStreetMap'
      }).addTo(map);

      mapInstanceRef.current = map;

      // Listen for drag end to resolve address
      map.on('moveend', () => {
        const center = map.getCenter();
        resolveAddress(center.lat, center.lng);
      });

      // Initial resolve for default center
      resolveAddress(defaultCenter[0], defaultCenter[1]);

      // --- AUTO LOCATE ---
      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(
            (position) => {
                const { latitude, longitude } = position.coords;
                // Ensure map still exists before updating
                if (mapInstanceRef.current) {
                    mapInstanceRef.current.setView([latitude, longitude], 18);
                    resolveAddress(latitude, longitude);
                }
            },
            (error) => {
                console.warn("Auto-location failed:", error);
            },
            { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
        );
      }
    } else {
        // If map already exists, ensure it resizes correctly if modal animation affected it
        setTimeout(() => {
            mapInstanceRef.current?.invalidateSize();
        }, 100);
    }

    return () => {
        if (mapInstanceRef.current) {
            mapInstanceRef.current.remove();
            mapInstanceRef.current = null;
        }
    };
  }, [isOpen]);

  const resolveAddress = async (lat: number, lng: number) => {
    setLoading(true);
    setCanConfirm(false);
    try {
        // Request address details and limit zoom to ensure building level detail if possible
        const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}&zoom=18&addressdetails=1`);
        const data = await response.json();

        let formatted = t.moveMap;
        if (data.address) {
            const { road, pedestrian, house_number, amenity, shop, tourism, suburb, neighbourhood, city, town, county } = data.address;

            // Priority: Place Name > Street + Number > District > City
            const place = amenity || shop || tourism;
            const street = road || pedestrian;
            const number = house_number;
            const district = suburb || neighbourhood;
            const cityVal = city || town || county;

            const parts = [];

            if (place) parts.push(place);

            const streetAddress = [street, number].filter(Boolean).join(', ');
            if (streetAddress) parts.push(streetAddress);
            else if (district) parts.push(district);

            if (parts.length === 0 && cityVal) parts.push(cityVal);

            formatted = parts.join(', ');

            if (!formatted) formatted = data.display_name.split(',')[0];
        }
        setCurrentAddress(formatted);
        setCanConfirm(true);
    } catch (e) {
        setCurrentAddress("Aniqlab bo'lmadi");
    } finally {
        setLoading(false);
    }
  };

  const handleLocateMe = () => {
    if (!navigator.geolocation) {
        alert("Geolocation is not supported by your browser");
        return;
    }

    setLoading(true);
    navigator.geolocation.getCurrentPosition(
        (position) => {
            const { latitude, longitude } = position.coords;
            if (mapInstanceRef.current) {
                mapInstanceRef.current.setView([latitude, longitude], 18);
                resolveAddress(latitude, longitude);
            }
        },
        () => {
            alert(t.locationPermissionDenied);
            setLoading(false);
        },
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-white animate-slide-up">
        {/* Header */}
        <div className="absolute top-0 left-0 right-0 z-[60] p-4 flex justify-between items-center pointer-events-none">
            <button 
                onClick={onClose} 
                className="w-10 h-10 bg-white shadow-md rounded-full flex items-center justify-center text-slate-900 pointer-events-auto"
            >
                <X size={20} />
            </button>
        </div>

        {/* Map */}
        <div className="flex-grow relative">
            <div ref={mapContainerRef} className="w-full h-full bg-slate-200" id="map"></div>

            {/* Center Pin */}
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-[55] pointer-events-none pb-8">
                <MapPin size={40} className="text-red-600 fill-red-600 drop-shadow-xl" />
                <div className="w-2 h-2 bg-black/20 rounded-full mx-auto blur-[1px]"></div>
            </div>

            {/* Locate Me FAB */}
            <button 
                onClick={handleLocateMe}
                className="absolute bottom-6 right-4 z-[55] w-12 h-12 bg-white rounded-full shadow-lg flex items-center justify-center text-red-600 active:scale-95 transition-transform"
            >
                <Navigation size={24} />
            </button>
        </div>

        {/* Bottom Sheet */}
        <div className="bg-white p-5 rounded-t-3xl shadow-[0_-5px_20px_rgba(0,0,0,0.1)] -mt-6 z-[60] relative">
            <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto mb-4"></div>

            <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">{t.delivery}</h3>
            <div className="flex items-start space-x-3 mb-6">
                <MapPin className="text-red-600 mt-1 flex-shrink-0" size={20} />
                <div>
                    {loading ? (
                        <div className="flex items-center space-x-2 text-slate-500">
                            <Loader2 className="animate-spin" size={16} />
                            <span className="font-medium">{t.locating}</span>
                        </div>
                    ) : (
                        <p className="text-lg font-bold text-slate-900 leading-tight">
                            {currentAddress}
                        </p>
                    )}
                </div>
            </div>

            <button 
                onClick={() => onConfirm(currentAddress)}
                disabled={!canConfirm || loading}
                className="w-full bg-red-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg shadow-red-200 active:scale-[0.98] transition-transform disabled:opacity-50 disabled:shadow-none"
            >
                {t.confirmLocation}
            </button>
        </div>
    </div>
  );
};

export default AddressModal;

