                            functionResponses: [{ id: fc.id, name: fc.name, response: { result } }]
                        });
                    });
                }
            }
          },
          onclose: () => setActive(false),
          onerror: () => { setActive(false); setConnecting(false); }
        }
      });
      sessionRef.current = sessionPromise;
    } catch (e) { setConnecting(false); }
  }, [stopAudio, user]);

  return (
    <div className="fixed bottom-24 lg:bottom-10 right-4 lg:right-10 z-50 flex flex-col items-center">
      {/* Voice Visualization Ripples */}
      {active && (
        <div className="absolute -inset-4 z-[-1]">
          <div className={`absolute inset-0 bg-red-500/20 rounded-full animate-ping ${!speaking && 'hidden'}`}></div>
          <div className={`absolute inset-0 bg-red-400/30 rounded-full animate-pulse delay-75 ${!active && 'hidden'}`}></div>
        </div>
      )}

      <button
        onClick={active ? disconnect : connect}
        className={`w-16 h-16 md:w-20 md:h-20 rounded-full shadow-2xl flex items-center justify-center transition-all duration-500 active:scale-90 ${
          active 
            ? 'bg-white text-red-600 border-4 border-red-600' 
            : 'bg-gradient-to-br from-red-600 to-red-700 text-white hover:shadow-red-300 hover:scale-110'
        }`}
      >
        {connecting ? (
          <Loader2 className="animate-spin w-8 h-8" />
        ) : active ? (
          <div className="relative">
             {speaking ? <Volume2 className="w-8 h-8 animate-pulse" /> : <Mic className="w-8 h-8" />}
             {/* Small status dot */}
             <span className="absolute -top-1 -right-1 w-3 h-3 bg-green-500 rounded-full border-2 border-white"></span>
          </div>
        ) : (
          <MicOff className="w-8 h-8" />
        )}
      </button>

      {active && (
        <div className="mt-3 bg-slate-900/90 backdrop-blur-sm text-white text-[10px] font-black px-4 py-1.5 rounded-full whitespace-nowrap shadow-xl border border-white/10 tracking-widest uppercase animate-bounce">
          {speaking ? 'AI gapirmoqda...' : 'Sizni eshityapman...'}
        </div>
      )}
    </div>
  );
};

