      const userIcon = L.divIcon({
          className: 'bg-transparent border-none',
          html: `<div class="relative flex items-center justify-center w-6 h-6"><span class="absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-50 animate-ping"></span><span class="relative inline-flex rounded-full h-4 w-4 bg-blue-500 border-2 border-white shadow-sm"></span></div>`,
          iconSize: [24, 24],
          iconAnchor: [12, 12]
      });
      if (userMarkerRef.current) { userMarkerRef.current.setLatLng([lat, lng]); } 
      else { userMarkerRef.current = L.marker([lat, lng], { icon: userIcon }).addTo(mapInstanceRef.current); }
  };

  const resolveAddress = async (lat: number, lng: number) => {
    setLoading(true);
    try {
        const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}&zoom=18&addressdetails=1`, {
            headers: { 'Accept-Language': 'uz-UZ,uz;q=0.9,en;q=0.8' }
        });
        const data = await response.json();
        let formatted = t.moveMap;
        if (data.address) {
            const { road, house_number, amenity, shop, city, town } = data.address;
            const place = amenity || shop;
            const street = road;
            const parts = [];
            if (place) parts.push(place);
            if (street) parts.push(`${street}${house_number ? ', ' + house_number : ''}`);
            if (parts.length === 0) parts.push(city || town);
            formatted = parts.join(', ');
        }
        setCurrentAddress(formatted);
        setCanConfirm(true);
    } catch (e) {
        setCurrentAddress(`${lat.toFixed(6)}, ${lng.toFixed(6)}`);
        setCanConfirm(true);
    } finally { setLoading(false); }
  };

  const handleConfirm = () => {
    if (orderType === 'delivery') {
        const parts = [currentAddress];
        const { entrance, floor, apartment, comment } = details;
        const extras = [];
        if (entrance) extras.push(`${t.entrance}: ${entrance}`);
        if (floor) extras.push(`${t.floor}: ${floor}`);
        if (apartment) extras.push(`${t.apartment}: ${apartment}`);
        let finalAddress = parts.join('');
        if (extras.length > 0) finalAddress += ` (${extras.join(', ')})`;
        if (comment) finalAddress += `. Note: ${comment}`;
        onConfirm(finalAddress);
    } else if (selectedBranch) {
        onConfirm(selectedBranch.name);
    }
  };

  const handleLocateMe = (e?: React.MouseEvent, silent: boolean = false) => {
    e?.stopPropagation();
    if (!navigator.geolocation) return;
    if (!silent) setLoading(true);
    navigator.geolocation.getCurrentPosition(
        (pos) => {
            const { latitude, longitude } = pos.coords;
            if (mapInstanceRef.current) {
                mapInstanceRef.current.flyTo([latitude, longitude], 18);
                updateUserMarker(latitude, longitude);
                resolveAddress(latitude, longitude);
            }
            setLoading(false);
        },
        () => setLoading(false),
        { enableHighAccuracy: true }
    );
  };

  const handleBranchSelect = (branch: Branch) => {
      setSelectedBranch(branch);
      setCanConfirm(true);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-white animate-slide-up">
        {/* Header */}
        <div className="p-4 flex items-center gap-4 bg-white border-b border-slate-100 shrink-0">
             <button onClick={onClose} className="w-10 h-10 flex items-center justify-center text-slate-900 bg-slate-50 rounded-xl">
                <X size={24} />
             </button>
             <h2 className="font-black text-lg uppercase tracking-tight italic">
                 {orderType === 'delivery' ? 'Yetkazib berish manzili' : 'Filialni tanlang'}
             </h2>
        </div>

        {orderType === 'delivery' ? (
            /* DELIVERY UI: Map + Search */
            <div className="flex-grow flex flex-col overflow-hidden">
                <div className="p-4">
                    <form onSubmit={(e) => e.preventDefault()} className="w-full h-12 bg-slate-50 rounded-xl flex items-center px-4 border border-slate-100 focus-within:ring-2 focus-within:ring-red-500">
                        <Search className="text-slate-400 mr-2" size={20} />
                        <input 
                            type="text" 
                            placeholder={t.searchAddress}
                            className="flex-1 h-full outline-none text-sm bg-transparent"
                        />
                    </form>
                </div>

                <div className="flex-grow relative">
                    <div ref={mapContainerRef} className="w-full h-full bg-slate-100 z-0"></div>
                    <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 z-10 pointer-events-none flex flex-col items-center transition-all ${isDragging ? '-translate-y-[calc(50%+10px)]' : '-translate-y-1/2'}`}>
                        <MapPin size={48} className="text-red-600 fill-red-600 drop-shadow-2xl" />
                    </div>
                    <button 
                        onClick={(e) => handleLocateMe(e)}
                        className="absolute bottom-6 right-4 z-10 w-12 h-12 bg-white rounded-full shadow-lg flex items-center justify-center text-red-600 border border-slate-100"
                    >
                        <Navigation size={24} className="fill-current" />
                    </button>
                </div>

                <div className="p-5 bg-white shadow-[0_-5px_20px_rgba(0,0,0,0.05)] rounded-t-3xl">
                    <div className="space-y-4">
                        <div>
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{t.delivery}</label>
                            <p className="text-base font-bold text-slate-900 line-clamp-2">{currentAddress}</p>
                        </div>
                        <div className="grid grid-cols-3 gap-2">
                             <input type="text" placeholder={t.entrance} className="p-3 bg-slate-50 rounded-xl text-sm border border-slate-100" value={details.entrance} onChange={e=>setDetails({...details, entrance: e.target.value})} />
                             <input type="text" placeholder={t.floor} className="p-3 bg-slate-50 rounded-xl text-sm border border-slate-100" value={details.floor} onChange={e=>setDetails({...details, floor: e.target.value})} />
                             <input type="text" placeholder={t.apartment} className="p-3 bg-slate-50 rounded-xl text-sm border border-slate-100" value={details.apartment} onChange={e=>setDetails({...details, apartment: e.target.value})} />
                        </div>
                        <button onClick={handleConfirm} disabled={!canConfirm} className="w-full bg-red-600 text-white py-4 rounded-xl font-black uppercase italic tracking-tighter shadow-lg shadow-red-200 disabled:opacity-50">Tasdiqlash</button>
                    </div>
                </div>
            </div>
        ) : (
            /* PICKUP UI: Branch List */
            <div className="flex-grow flex flex-col bg-slate-50 overflow-y-auto">
                <div className="p-4 space-y-3">
                    {BRANCHES.map((branch) => (
                        <button 
                            key={branch.id}
                            onClick={() => handleBranchSelect(branch)}
                            className={`w-full text-left p-4 rounded-2xl border transition-all flex items-center justify-between ${
                                selectedBranch?.id === branch.id 
                                ? 'bg-white border-red-600 shadow-md ring-1 ring-red-600' 
                                : 'bg-white border-slate-200 hover:border-slate-300'
                            }`}
                        >
                            <div className="flex gap-4">
                                <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${selectedBranch?.id === branch.id ? 'bg-red-50 text-red-600' : 'bg-slate-100 text-slate-400'}`}>
                                    <MapPin size={24} />
                                </div>
                                <div>
                                    <h4 className="font-black text-slate-900 uppercase italic tracking-tighter">{branch.name}</h4>
                                    <p className="text-xs text-slate-500 font-medium mb-1">{branch.address}</p>
                                    <div className="flex items-center gap-1 text-[10px] font-bold text-slate-400">
                                        <Clock size={12} /> <span>{branch.workTime}</span>
                                    </div>
                                </div>
                            </div>
                            {selectedBranch?.id === branch.id && (
                                <CheckCircle2 size={24} className="text-red-600 fill-red-50 shrink-0" />
                            )}
                        </button>
                    ))}
                </div>

                <div className="mt-auto p-4 bg-white border-t border-slate-100">
                    <button 
                        onClick={handleConfirm}
                        disabled={!selectedBranch}
                        className="w-full bg-red-600 text-white py-4 rounded-xl font-black uppercase italic tracking-tighter shadow-lg shadow-red-200 disabled:opacity-50"
                    >
                        Tanlash
                    </button>
                </div>
            </div>
        )}
    </div>
  );
};

