import React, { useState } from 'react';
import { useCart } from '../context/CartContext';
import { useOrders } from '../context/OrderContext';
import { useAuth } from '../context/AuthContext';
import { Minus, Plus, CheckCircle, ShoppingBag, Phone, ChevronDown } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { formatCurrency } from '../utils/format';
import AddressModal from '../components/AddressModal';

const Cart = () => {
  const { items, updateQuantity, total, clearCart } = useCart();
  const { placeOrder } = useOrders();
  const { user, login, currentAddress, setCurrentAddress, orderType, setOrderType, selectedBranch } = useAuth();
  const navigate = useNavigate();
  const { t } = useLanguage();

  const [success, setSuccess] = useState(false);
  const [guestPhone, setGuestPhone] = useState('');
  const [error, setError] = useState('');
  const [isAddressModalOpen, setIsAddressModalOpen] = useState(false);

  const handleCheckout = () => {
    if (!user && guestPhone.length < 9) {
        setError('Iltimos, telefon raqamingizni kiriting');
        return;
    }

    const finalPhone = user ? user.phone : guestPhone;
    const finalName = user ? (user.name || 'Mijoz') : 'Mehmon';

    if (!user) {
        login(guestPhone, 'Mijoz');
    }

    placeOrder(
        items, 
        total, 
        orderType === 'delivery' ? currentAddress : (selectedBranch ? selectedBranch.name : 'Filialdan olib ketish'), 
        finalPhone,
        finalName
    );

    clearCart();
    setSuccess(true);
    setTimeout(() => {
        setSuccess(false);
        navigate('/');
    }, 2500);
  };

  const displayLocation = orderType === 'delivery' 
    ? currentAddress 
    : (selectedBranch ? selectedBranch.name : "Filialni tanlang");

  if (success) {
      return (
          <div className="h-[80vh] flex flex-col items-center justify-center p-6 text-center animate-slide-up">
              <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mb-6">
                <CheckCircle className="text-green-500 w-16 h-16" />
              </div>
              <h1 className="text-3xl font-black text-slate-900 mb-2 italic uppercase">Qabul qilindi!</h1>
              <p className="text-slate-500 max-w-xs">Buyurtmangiz tayyorlanmoqda. Tez orada aloqaga chiqamiz.</p>
              <button 
                  onClick={() => navigate('/')}
                  className="mt-8 bg-red-600 text-white px-10 py-3 rounded-xl font-bold shadow-lg shadow-red-200"
              >
                  Asosiy sahifa
              </button>
          </div>
      )
  }

  if (items.length === 0) {
    return (
        <div className="flex flex-col items-center justify-center h-[80vh] px-4">
            <ShoppingBag size={80} className="text-slate-200 mb-6" />
            <h2 className="text-2xl font-bold text-slate-800 mb-2">{t.emptyCart}</h2>
            <button 
                onClick={() => navigate('/menu')}
                className="mt-6 bg-red-600 text-white px-10 py-4 rounded-xl font-bold"
            >
                {t.goToMenu}
            </button>
        </div>
    );
  }

  return (
    <div className="px-4 md:px-8 py-6 max-w-6xl mx-auto min-h-screen pb-40 lg:pb-10">
      <h1 className="text-3xl font-black mb-8 text-slate-900 italic uppercase tracking-tighter">Savat</h1>

      <div className="flex flex-col lg:flex-row gap-8">
          {/* List of items */}
          <div className="flex-1 space-y-4">
            {items.map(item => (
                <div key={item.id} className="bg-white p-4 rounded-3xl flex items-center shadow-sm border border-slate-100">
                    <img src={item.image} alt={item.name} className="w-20 h-20 rounded-2xl object-cover bg-slate-50" />
                    <div className="ml-4 flex-grow">
                        <h3 className="font-bold text-slate-800 text-base line-clamp-1">{item.name}</h3>
                        <p className="text-red-600 font-black text-sm">{formatCurrency(item.price)}</p>
                    </div>
                    <div className="flex items-center bg-slate-100 rounded-xl p-1.5">
                        <button onClick={() => updateQuantity(item.id, -1)} className="p-1 text-slate-500 hover:text-red-600"><Minus size={18}/></button>
                        <span className="px-3 font-black text-slate-800">{item.quantity}</span>
                        <button onClick={() => updateQuantity(item.id, 1)} className="p-1 text-slate-500 hover:text-red-600"><Plus size={18}/></button>
                    </div>
                </div>
            ))}
          </div>

          {/* Checkout Info Sidebar */}
          <div className="w-full lg:w-96">
            <div className="bg-white p-6 rounded-[2.5rem] shadow-2xl shadow-slate-200 border border-slate-50 space-y-6">

                <div className="space-y-4">
                    <div className="flex flex-col">
                        <span className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em] mb-1">
                            {orderType === 'delivery' ? 'Yetkazib berish' : 'Olib ketish'}
                        </span>
                        <button 
                            onClick={() => setIsAddressModalOpen(true)}
                            className="flex items-center gap-1 group text-left"
                        >
                            <span className="text-lg font-black text-slate-900 border-b-2 border-dashed border-slate-200 group-hover:border-red-600 transition-colors">
                                {displayLocation}
                            </span>
                            <ChevronDown size={20} className="text-red-600 shrink-0" />
                        </button>
                    </div>

                    {/* Toggle Switch */}
                    <div className="bg-slate-100 p-1.5 rounded-2xl flex relative">
                        <button 
                            onClick={() => setOrderType('delivery')}
                            className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all z-10 ${orderType === 'delivery' ? 'text-white' : 'text-slate-400'}`}
                        >
                            Yetkazib berish
                        </button>
                        <button 
                            onClick={() => setOrderType('pickup')}
                            className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all z-10 ${orderType === 'pickup' ? 'text-white' : 'text-slate-400'}`}
                        >
                            Olib ketish
                        </button>
                        <div 
                            className={`absolute top-1.5 bottom-1.5 w-[calc(50%-6px)] bg-red-600 rounded-xl transition-all duration-300 shadow-lg shadow-red-200 ${orderType === 'delivery' ? 'left-1.5' : 'left-[calc(50%+1.5px)]'}`}
                        ></div>
                    </div>
                </div>

                {!user && (
                    <div className="space-y-3 pt-4 border-t border-slate-50">
                        <h3 className="font-black text-slate-900 uppercase text-[10px] tracking-widest flex items-center gap-2">
                           <Phone size={14} className="text-red-600" /> Kontakt Ma'lumotlari
                        </h3>
                        <div className="relative">
                            <input 
                                type="tel" 
                                placeholder="+998..." 
                                className={`w-full p-4 bg-slate-50 rounded-2xl border-2 outline-none transition-all font-bold text-lg ${error ? 'border-red-400' : 'border-slate-50 focus:border-red-600 focus:bg-white'}`}
                                value={guestPhone}
                                onChange={e => { setGuestPhone(e.target.value); setError(''); }}
                            />
                            {error && <p className="text-[10px] text-red-500 font-bold mt-2 ml-2 uppercase tracking-wider">{error}</p>}
                        </div>
                    </div>
                )}

                <div className="pt-6 border-t border-slate-100">
                    <div className="flex justify-between items-center mb-6">
                        <span className="font-bold text-slate-400 uppercase text-xs tracking-widest">Jami:</span>
                        <div className="text-right">
                             <span className="font-black text-3xl text-red-600">{formatCurrency(total)}</span>
                             <p className="text-[10px] text-slate-400 font-bold">QQS bilan birga</p>
                        </div>
                    </div>

                    <button 
                        className="w-full bg-red-600 text-white py-5 rounded-[1.5rem] font-black text-xl shadow-xl shadow-red-100 active:scale-95 transition-all uppercase italic tracking-tighter"
                        onClick={handleCheckout}
                    >
