interface LanguageContextType {
  lang: Language;
  setLang: (lang: Language) => void;
  t: Translations;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export const LanguageProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [lang, setLang] = useState<Language>('uz');

  return (
    <LanguageContext.Provider value={{ lang, setLang, t: translations[lang] }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (!context) throw new Error('useLanguage must be used within LanguageProvider');
  return context;
};

import React, { useState } from 'react';
import { useCart } from '../context/CartContext';
import { useOrders } from '../context/OrderContext';
import { useAuth } from '../context/AuthContext';
import { Minus, Plus, CheckCircle, ShoppingBag, Phone, ChevronDown, User as UserIcon } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { formatCurrency } from '../utils/format';
import AddressModal from '../components/AddressModal';

const Cart = () => {
  const { items, updateQuantity, total, clearCart } = useCart();
  const { placeOrder } = useOrders();
  const { user, login, currentAddress, setCurrentAddress, orderType, setOrderType, selectedBranch } = useAuth();
  const navigate = useNavigate();
  const { t } = useLanguage();

  const [success, setSuccess] = useState(false);
  const [guestPhone, setGuestPhone] = useState('');
  const [guestName, setGuestName] = useState('');
  const [error, setError] = useState('');
  const [isAddressModalOpen, setIsAddressModalOpen] = useState(false);

  const handleCheckout = () => {
    if (!user) {
        if (guestName.trim().length < 2) {
            setError('Iltimos, ismingizni kiriting');
            return;
        }
        if (guestPhone.length < 9) {
            setError('Iltimos, telefon raqamingizni to\'g\'ri kiriting');
            return;
        }
    }

    const finalPhone = user ? user.phone : guestPhone;
    const finalName = user ? (user.name || 'Mijoz') : guestName;

    if (!user) {
        login(guestPhone, guestName);
    }

    placeOrder(
        items, 
        total, 
        orderType === 'delivery' ? currentAddress : (selectedBranch ? selectedBranch.name : 'Filialdan olib ketish'), 
        finalPhone,
        finalName
    );

    clearCart();
    setSuccess(true);
    setTimeout(() => {
        setSuccess(false);
        navigate('/');
    }, 2500);
  };

  const displayLocation = orderType === 'delivery' 
    ? currentAddress 
    : (selectedBranch ? selectedBranch.name : "Filialni tanlang");

  if (success) {
      return (
          <div className="h-[80vh] flex flex-col items-center justify-center p-6 text-center animate-slide-up">
