                        </h3>
                        <div className="space-y-3">
                            <input type="text" placeholder={t.namePlaceholder} className={`w-full p-4 bg-slate-50 rounded-2xl border-2 outline-none transition-all font-black text-lg ${error && guestName.trim().length < 2 ? 'border-red-500' : 'border-slate-100 focus:border-red-600 focus:bg-white'}`} value={guestName} onChange={e => { setGuestName(e.target.value); setError(''); }} />
                            <input type="tel" placeholder="+998..." className={`w-full p-4 bg-slate-50 rounded-2xl border-2 outline-none transition-all font-black text-lg ${error && guestPhone.length < 9 ? 'border-red-500' : 'border-slate-100 focus:border-red-600 focus:bg-white'}`} value={guestPhone} onChange={e => { setGuestPhone(e.target.value); setError(''); }} />
                            {error && <p className="text-[10px] text-red-500 font-black uppercase tracking-widest ml-2">{error}</p>}
                        </div>
                    </div>
                )}

                <div className="pt-6 border-t border-slate-100">
                    <div className="flex justify-between items-end mb-6">
                        <span className="font-black text-slate-400 uppercase text-[10px] tracking-widest mb-1">Jami:</span>
                        <div className="text-right">
                             <span className="font-black text-3xl text-red-600 italic tracking-tighter">{formatCurrency(total)}</span>
                             <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">QQS bilan birga</p>
                        </div>
                    </div>

                    <button 
                        className={`w-full py-5 rounded-2xl font-black text-xl shadow-2xl active:scale-95 transition-all uppercase italic tracking-tighter ${paymentMethod === 'paynet' ? 'bg-green-600 text-white shadow-green-200' : 'bg-red-600 text-white shadow-red-200'}`}
                        onClick={handleCheckout}
                    >
                        {paymentMethod === 'paynet' ? 'PAYNET BILAN TO\'LASH' : 'RASMIYLASHTIRISH'}
                    </button>
                </div>
            </div>
          </div>
      </div>

      <AddressModal isOpen={isAddressModalOpen} onClose={() => setIsAddressModalOpen(false)} onConfirm={(addr) => { if (orderType === 'delivery') setCurrentAddress(addr); setIsAddressModalOpen(false); }} />
    </div>
  );
};

