import React, { useState } from 'react';
import { useCart } from '../context/CartContext';
import { useOrders } from '../context/OrderContext';
import { useAuth } from '../context/AuthContext';
import { Minus, Plus, CheckCircle, ShoppingBag, Phone, ChevronDown, User as UserIcon, Wallet, CreditCard, QrCode, Ticket } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { formatCurrency } from '../utils/format';
import AddressModal from '../components/AddressModal';

const Cart = () => {
  const { items, updateQuantity, total, clearCart } = useCart();
  const { placeOrder } = useOrders();
  const { user, login, currentAddress, setCurrentAddress, orderType, setOrderType, selectedBranch } = useAuth();
  const navigate = useNavigate();
  const { t } = useLanguage();

  const [success, setSuccess] = useState(false);
  const [guestPhone, setGuestPhone] = useState('');
  const [guestName, setGuestName] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'terminal' | 'paynet'>('cash');
  const [error, setError] = useState('');
  const [isAddressModalOpen, setIsAddressModalOpen] = useState(false);
  const [promoCode, setPromoCode] = useState('');
  const [discount, setDiscount] = useState(0);

  const applyPromo = () => {
    if (promoCode.toUpperCase() === 'KFC2024') {
        setDiscount(total * 0.1); // 10% discount
        alert("Promo-kod qabul qilindi! 10% chegirma berildi.");
    } else {
        alert("Noto'g'ri promo-kod");
    }
  };

  const handleCheckout = () => {
    if (!user) {
        if (guestName.trim().length < 2) {
            setError('Iltimos, ismingizni kiriting');
            return;
        }
        if (guestPhone.length < 9) {
            setError('Iltimos, telefon raqamingizni to\'g\'ri kiriting');
            return;
        }
    }

    const finalPhone = user ? user.phone : guestPhone;
    const finalName = user ? (user.name || 'Mijoz') : guestName;
    const paymentLabel = paymentMethod === 'cash' ? t.cash : (paymentMethod === 'terminal' ? t.terminal : t.paynetQR);

    if (!user) {
        login(guestPhone, guestName);
    }

    placeOrder(
        items, 
        total - discount, 
        orderType === 'delivery' ? currentAddress : (selectedBranch ? selectedBranch.name : 'Filialdan olib ketish'), 
        finalPhone,
        finalName,
        paymentLabel
    );

    clearCart();
    setSuccess(true);
    setTimeout(() => {
        setSuccess(false);
        navigate('/');
    }, 2500);
  };

  const displayLocation = orderType === 'delivery' 
    ? currentAddress 
    : (selectedBranch ? selectedBranch.name : "Filialni tanlang");

  if (success) {
      return (
          <div className="h-[80vh] flex flex-col items-center justify-center p-6 text-center animate-slide-up">
              <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mb-6">
                <CheckCircle className="text-green-500 w-16 h-16" />
              </div>
              <h1 className="text-3xl font-black text-slate-900 mb-2 italic uppercase">Qabul qilindi!</h1>
              <p className="text-slate-500 max-w-xs">Buyurtmangiz tayyorlanmoqda. To'lov turi: <span className="font-bold text-slate-900">{paymentMethod === 'paynet' ? 'Paynet QR' : paymentMethod}</span></p>
              <button 
                  onClick={() => navigate('/')}
                  className="mt-8 bg-red-600 text-white px-10 py-3 rounded-xl font-bold shadow-lg shadow-red-200"
              >
                  Asosiy sahifa
              </button>
          </div>
      )
  }

  if (items.length === 0) {
    return (
        <div className="flex flex-col items-center justify-center h-[80vh] px-4">
            <ShoppingBag size={80} className="text-slate-200 mb-6" />
            <h2 className="text-2xl font-bold text-slate-800 mb-2">{t.emptyCart}</h2>
            <button onClick={() => navigate('/menu')} className="mt-6 bg-red-600 text-white px-10 py-4 rounded-xl font-bold">{t.goToMenu}</button>
        </div>
    );
  }

  return (
    <div className="px-4 md:px-8 py-6 max-w-6xl mx-auto min-h-screen pb-40 lg:pb-10">
      <h1 className="text-3xl font-black mb-8 text-slate-900 italic uppercase tracking-tighter">SAVAT</h1>

      <div className="flex flex-col lg:flex-row gap-8">
          <div className="flex-1 space-y-4">
            {items.map(item => (
                <div key={item.id} className="bg-white p-4 rounded-3xl flex items-center shadow-sm border border-slate-100 group">
                    <div className="w-24 h-24 rounded-2xl overflow-hidden bg-slate-50 shrink-0 border border-slate-100">
                        <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                    </div>
                    <div className="ml-4 flex-grow">
                        <h3 className="font-black text-slate-900 text-lg line-clamp-1 italic uppercase tracking-tighter">{item.name}</h3>
                        <p className="text-red-600 font-black text-base">{formatCurrency(item.price)}</p>
                    </div>
                    <div className="flex items-center bg-slate-100/50 rounded-2xl p-2 gap-1">
                        <button onClick={() => updateQuantity(item.id, -1)} className="w-8 h-8 flex items-center justify-center bg-white rounded-xl text-slate-400 hover:text-red-600 shadow-sm"><Minus size={18}/></button>
                        <span className="px-4 font-black text-slate-900 text-lg">{item.quantity}</span>
                        <button onClick={() => updateQuantity(item.id, 1)} className="w-8 h-8 flex items-center justify-center bg-white rounded-xl text-slate-400 hover:text-red-600 shadow-sm"><Plus size={18}/></button>
                    </div>
                </div>
            ))}

            {/* Promo Code Input */}
            <div className="bg-white p-5 rounded-[2rem] border border-dashed border-slate-200 mt-6 flex items-center gap-4">
                <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-400"><Ticket size={24}/></div>
                <input 
                    type="text" 
                    placeholder="PROMO-KOD" 
                    className="flex-grow bg-transparent font-black text-lg outline-none uppercase placeholder:text-slate-200"
                    value={promoCode}
                    onChange={e => setPromoCode(e.target.value)}
                />
                <button 
                    onClick={applyPromo}
                    className="bg-slate-900 text-white px-6 py-3 rounded-xl font-black text-xs uppercase italic tracking-widest active:scale-95 transition-all"
                >
                    QO'LLASH
                </button>
            </div>
          </div>

          <div className="w-full lg:w-96">
            <div className="bg-white p-6 rounded-[2.5rem] shadow-2xl shadow-slate-200 border border-slate-50 space-y-6">

                <div className="space-y-4">
                    <div className="flex flex-col">
                        <span className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em] mb-1">{orderType === 'delivery' ? t.delivery : t.pickup}</span>
                        <button onClick={() => setIsAddressModalOpen(true)} className="flex items-center gap-1 group text-left">
                            <span className="text-lg font-black text-slate-900 border-b-2 border-dashed border-slate-200 group-hover:border-red-600 transition-colors">{displayLocation}</span>
                            <ChevronDown size={20} className="text-red-600 shrink-0" />
                        </button>
                    </div>
                </div>

                <div className="space-y-4 pt-4 border-t border-slate-100">
                    <h3 className="font-black text-slate-900 uppercase text-[10px] tracking-[0.2em] flex items-center gap-2">
                       <Wallet size={14} className="text-red-600" /> {t.paymentMethod}
                    </h3>
                    <div className="grid grid-cols-1 gap-2">
                        <button onClick={() => setPaymentMethod('cash')} className={`p-4 rounded-2xl flex items-center gap-4 border-2 transition-all ${paymentMethod === 'cash' ? 'border-red-600 bg-red-50/30' : 'border-slate-50 bg-slate-50/50 hover:border-slate-200'}`}>
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${paymentMethod === 'cash' ? 'bg-red-600 text-white' : 'bg-white text-slate-400'}`}><Wallet size={20}/></div>
                            <span className="font-black uppercase italic tracking-tighter text-slate-900">{t.cash}</span>
                        </button>
                        <button onClick={() => setPaymentMethod('terminal')} className={`p-4 rounded-2xl flex items-center gap-4 border-2 transition-all ${paymentMethod === 'terminal' ? 'border-red-600 bg-red-50/30' : 'border-slate-50 bg-slate-50/50 hover:border-slate-200'}`}>
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${paymentMethod === 'terminal' ? 'bg-red-600 text-white' : 'bg-white text-slate-400'}`}><CreditCard size={20}/></div>
                            <span className="font-black uppercase italic tracking-tighter text-slate-900">{t.terminal}</span>
                        </button>
                        <button onClick={() => setPaymentMethod('paynet')} className={`p-4 rounded-2xl flex items-center gap-4 border-2 transition-all relative overflow-hidden group ${paymentMethod === 'paynet' ? 'border-green-600 bg-green-50/30' : 'border-slate-50 bg-slate-50/50 hover:border-slate-200'}`}>
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-colors ${paymentMethod === 'paynet' ? 'bg-green-600 text-white' : 'bg-white text-slate-400'}`}><QrCode size={20}/></div>
                            <div className="flex flex-col items-start">
                                <span className={`font-black uppercase italic tracking-tighter ${paymentMethod === 'paynet' ? 'text-green-700' : 'text-slate-900'}`}>{t.paynetQR}</span>
                                <span className="text-[8px] font-black text-green-600/70 uppercase tracking-[0.1em]">YATT uchun qulay (2026)</span>
                            </div>
                        </button>
                    </div>
                </div>

                {!user && (
                    <div className="space-y-4 pt-4 border-t border-slate-100">
                        <h3 className="font-black text-slate-900 uppercase text-[10px] tracking-[0.2em] flex items-center gap-2">
                           <UserIcon size={14} className="text-red-600" /> KONTAKT MA'LUMOTLARI
                        </h3>
                        <div className="space-y-3">
                            <input type="text" placeholder={t.namePlaceholder} className={`w-full p-4 bg-slate-50 rounded-2xl border-2 outline-none transition-all font-black text-lg ${error && guestName.trim().length < 2 ? 'border-red-500' : 'border-slate-100 focus:border-red-600 focus:bg-white'}`} value={guestName} onChange={e => { setGuestName(e.target.value); setError(''); }} />
                            <input type="tel" placeholder="+998..." className={`w-full p-4 bg-slate-50 rounded-2xl border-2 outline-none transition-all font-black text-lg ${error && guestPhone.length < 9 ? 'border-red-500' : 'border-slate-100 focus:border-red-600 focus:bg-white'}`} value={guestPhone} onChange={e => { setGuestPhone(e.target.value); setError(''); }} />
                            {error && <p className="text-[10px] text-red-500 font-black uppercase tracking-widest ml-2">{error}</p>}
                        </div>
                    </div>
                )}

                <div className="pt-6 border-t border-slate-100">
                    <div className="space-y-2 mb-6">
                        <div className="flex justify-between items-center text-slate-400 text-[10px] font-black uppercase tracking-widest">
                            <span>Savat summasi:</span>
                            <span>{formatCurrency(total)}</span>
                        </div>
                        {discount > 0 && (
                            <div className="flex justify-between items-center text-green-600 text-[10px] font-black uppercase tracking-widest">
                                <span>Chegirma:</span>
                                <span>-{formatCurrency(discount)}</span>
                            </div>
                        )}
                        <div className="flex justify-between items-end pt-2">
                            <span className="font-black text-slate-400 uppercase text-[10px] tracking-widest mb-1">Jami:</span>
                            <div className="text-right">
                                 <span className="font-black text-3xl text-red-600 italic tracking-tighter">{formatCurrency(total - discount)}</span>
                                 <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">QQS bilan birga</p>
                            </div>
                        </div>
                    </div>

                    <button 
                        className={`w-full py-5 rounded-2xl font-black text-xl shadow-2xl active:scale-95 transition-all uppercase italic tracking-tighter ${paymentMethod === 'paynet' ? 'bg-green-600 text-white shadow-green-200' : 'bg-red-600 text-white shadow-red-200'}`}
                        onClick={handleCheckout}
                    >
                        {paymentMethod === 'paynet' ? 'PAYNET BILAN TO\'LASH' : 'RASMIYLASHTIRISH'}
                    </button>
                </div>
            </div>
          </div>
      </div>

      <AddressModal isOpen={isAddressModalOpen} onClose={() => setIsAddressModalOpen(false)} onConfirm={(addr) => { if (orderType === 'delivery') setCurrentAddress(addr); setIsAddressModalOpen(false); }} />
    </div>
  );
};

