                            </div>
                        </button>
                    </div>
                </div>

                {/* Contact Info (for guests) */}
                {!user && (
                    <div className="space-y-4 pt-4 border-t border-slate-100">
                        <h3 className="font-black text-slate-900 uppercase text-[10px] tracking-[0.2em] flex items-center gap-2">
                           <UserIcon size={14} className="text-red-600" /> KONTAKT MA'LUMOTLARI
                        </h3>
                        <div className="space-y-3">
                            <input 
                                type="text" 
                                placeholder={t.namePlaceholder} 
                                className={`w-full p-4 bg-slate-50 rounded-2xl border-2 outline-none transition-all font-black text-lg ${error && guestName.trim().length < 2 ? 'border-red-500' : 'border-slate-100 focus:border-red-600 focus:bg-white'}`}
