import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Mic, MicOff, Loader2, Volume2 } from 'lucide-react';
import { GoogleGenAI, LiveServerMessage, Modality, FunctionDeclaration, Type } from '@google/genai';
import { useCart } from '../context/CartContext';
import { useMenu } from '../context/MenuContext';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { DEFAULT_SYSTEM_INSTRUCTION } from '../constants';
import { createBlob, decode, decodeAudioData } from '../utils/audio';

const addToOrderDecl: FunctionDeclaration = {
  name: 'addToOrder',
  description: 'Add an item to the cart using its menu name.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      itemName: { type: Type.STRING, description: 'The exact name of the product from the menu.' },
      quantity: { type: Type.NUMBER, description: 'Quantity to add (minimum 1).' }
    },
    required: ['itemName']
  }
};

const getCartStatusDecl: FunctionDeclaration = {
  name: 'getCartStatus',
  description: 'Get current cart items and total price.',
  parameters: { type: Type.OBJECT, properties: {} }
};

const confirmOrderDecl: FunctionDeclaration = {
  name: 'confirmOrder',
  description: 'Go to checkout page.',
  parameters: { type: Type.OBJECT, properties: {} }
};

const LiveAgent: React.FC = () => {
  const [active, setActive] = useState(false);
  const [connecting, setConnecting] = useState(false);
  const [speaking, setSpeaking] = useState(false);

  const { addToCart, items, total } = useCart();
  const { products } = useMenu();
  const navigate = useNavigate();

  const addToCartRef = useRef(addToCart);
  const productsRef = useRef(products);
  const itemsRef = useRef(items);
  const totalRef = useRef(total);
  const navigateRef = useRef(navigate);

  useEffect(() => {
    addToCartRef.current = addToCart;
    productsRef.current = products;
    itemsRef.current = items;
    totalRef.current = total;
    navigateRef.current = navigate;
  }, [addToCart, products, items, total, navigate]);

  const audioContextRef = useRef<AudioContext | null>(null);
  const inputContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<any>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const findProduct = (name: string) => {
    if (!name) return null;
    const list = productsRef.current;
    const searchName = name.toLowerCase().trim();

    let found = list.find(p => p.name.toLowerCase() === searchName);
    if (found) return found;

    found = list.find(p => p.name.toLowerCase().includes(searchName) || searchName.includes(p.name.toLowerCase()));
    if (found) return found;

    const keywords = searchName.replace(/lar|cha|ni|dan|ning/g, '').split(' ');
    found = list.find(p => {
        const pName = p.name.toLowerCase();
        return keywords.some(k => k.length > 2 && pName.includes(k));
    });

    return found;
  };

  const stopAudio = useCallback(() => {
    if (audioContextRef.current) audioContextRef.current.suspend();
    sourcesRef.current.forEach(source => { try { source.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    setSpeaking(false);
  }, []);

  const disconnect = useCallback(() => {
    if (sessionRef.current) {
        try { sessionRef.current.close(); } catch(e) {}
        sessionRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (inputContextRef.current) { inputContextRef.current.close(); inputContextRef.current = null; }
    if (audioContextRef.current) { audioContextRef.current.close(); audioContextRef.current = null; }
    setActive(false);
    setConnecting(false);
    setSpeaking(false);
  }, []);

  const connect = useCallback(async () => {
    if (!process.env.API_KEY) return alert("API Key topilmadi.");

    try {
      setConnecting(true);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const inputContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      inputContextRef.current = inputContext;

      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = audioContext;
      nextStartTimeRef.current = 0;

      const menuList = productsRef.current.map(p => `- ${p.name}: ${p.price} so'm`).join('\n');

      // Admin kiritgan ko'rsatmalarni olish yoki standartni ishlatish
      const savedInstruction = localStorage.getItem('ai_system_instruction') || DEFAULT_SYSTEM_INSTRUCTION;

      const dynamicInstruction = `
        ${savedInstruction}

        MENYU RO'YXATI:
        ${menuList}

        TEKNIK QOIDALAR: 
        1. Agar mijoz biror narsa buyurtma qilsa, "addToOrder" funksiyasini chaqiring. 
        2. Funksiya muvaffaqiyatli bajarilganini tasdiqlash uchun natijani kuting.
        3. Agar mahsulot topilmasa, mijozga menyuda bor narsalarni taklif qiling.
        4. Har doim "getCartStatus" orqali joriy savat holatini tekshirib turing.
      `;

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction: dynamicInstruction,
          tools: [{ functionDeclarations: [addToOrderDecl, getCartStatusDecl, confirmOrderDecl] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }
        },
        callbacks: {
          onopen: () => {
            setConnecting(false);
            setActive(true);
            const source = inputContext.createMediaStreamSource(stream);
            const scriptProcessor = inputContext.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(session => session.sendRealtimeInput({ media: createBlob(inputData) }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputContext.destination);
          },
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) {
                setSpeaking(true);
                if (audioContext.state === 'suspended') await audioContext.resume();
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, audioContext.currentTime);
                const audioBuffer = await decodeAudioData(decode(audioData), audioContext, 24000, 1);
                const source = audioContext.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(audioContext.destination);
                source.onended = () => {
                    sourcesRef.current.delete(source);
                    if(sourcesRef.current.size === 0) setSpeaking(false);
                };
                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += audioBuffer.duration;
                sourcesRef.current.add(source);
            }

            if (msg.serverContent?.interrupted) stopAudio();

            if (msg.toolCall) {
                for (const fc of msg.toolCall.functionCalls) {
                    let result: any = { error: 'Not found' };
                    if (fc.name === 'addToOrder') {
                        const { itemName, quantity } = fc.args as any;
                        const product = findProduct(itemName);
                        if (product) {
                            addToCartRef.current(product, Number(quantity) || 1);
                            result = { success: true, message: `${product.name} savatga qo'shildi.` };
                        } else {
                            result = { error: `Kechirasiz, "${itemName}" menyuda topilmadi.` };
                        }
                    } else if (fc.name === 'getCartStatus') {
                        result = { 
                            items: itemsRef.current.map(i => `${i.quantity}x ${i.name}`),
                            total: totalRef.current 
                        };
                    } else if (fc.name === 'confirmOrder') {
                        navigateRef.current('/cart');
                        result = { success: true };
                    }

                    sessionPromise.then(session => {
                        session.sendToolResponse({
                            functionResponses: { id: fc.id, name: fc.name, response: { result } }
                        });
                    });
                }
            }
          },
          onclose: () => setActive(false),
          onerror: () => setActive(false)
        }
      });
      sessionRef.current = sessionPromise;
    } catch (e) { setConnecting(false); }
  }, [stopAudio]);

  return (
    <div className="fixed bottom-24 lg:bottom-10 right-4 lg:right-10 z-50 flex flex-col items-center">
      {active && (
        <div className="absolute -inset-4 z-[-1]">
          <div className={`absolute inset-0 bg-red-500/20 rounded-full animate-ping ${!speaking && 'hidden'}`}></div>
          <div className={`absolute inset-0 bg-red-400/30 rounded-full animate-pulse ${!active && 'hidden'}`}></div>
        </div>
      )}

      <button
        onClick={active ? disconnect : connect}
        className={`w-16 h-16 md:w-20 md:h-20 rounded-full shadow-2xl flex items-center justify-center transition-all duration-500 active:scale-90 ${
          active ? 'bg-white text-red-600 border-4 border-red-600' : 'bg-red-600 text-white hover:scale-110'
        }`}
      >
        {connecting ? <Loader2 className="animate-spin w-8 h-8" /> : active ? <Volume2 className="w-8 h-8" /> : <Mic className="w-8 h-8" />}
      </button>

      {active && (
        <div className="mt-3 bg-slate-900 text-white text-[10px] font-black px-4 py-1.5 rounded-full shadow-xl uppercase tracking-widest animate-bounce">
          {speaking ? 'AI gapirmoqda...' : 'Eshityapman...'}
        </div>
      )}
    </div>
  );
};

