                    sessionPromise.then(session => {
                        session.sendToolResponse({
                            functionResponses: { id: fc.id, name: fc.name, response: { result } }
                        });
                    });
                }
            }
          },
          onclose: () => setActive(false),
          onerror: (e) => {
            console.error("AI Session error:", e);
            setError("Ulanishda uzilish.");
            disconnect();
          }
        }
      });
      sessionRef.current = sessionPromise;
    } catch (e) { 
      setConnecting(false); 
      setError("Mikrofon xatosi.");
    }
  }, [stopAudio, disconnect]);

  return (
    <div className="fixed bottom-24 lg:bottom-10 right-4 lg:right-10 z-50 flex flex-col items-center">
      {error && (
          <div className="mb-4 bg-white p-3 rounded-2xl shadow-xl border border-red-100 flex items-center gap-2 text-red-600 text-[10px] font-black uppercase">
