import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useMenu } from '../context/MenuContext';
import { useCart } from '../context/CartContext';
import { formatCurrency } from '../utils/format';
import { ChevronLeft, Plus, Minus, ShoppingBag, Info, Flame, Scale, ChevronRight } from 'lucide-react';

const ProductDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { products } = useMenu();
  const { addToCart } = useCart();
  const [quantity, setQuantity] = useState(1);
  const [added, setAdded] = useState(false);
  const [activeImageIndex, setActiveImageIndex] = useState(0);

  const product = products.find(p => p.id === id);

  // Combine main image and gallery images for the display list
  const allImages = product ? [product.image, ...(product.images || [])].filter(Boolean).slice(0, 3) : [];

  useEffect(() => {
    if (product) {
      document.title = `${product.name} | KFC Uzbekistan`;

      const metaTitle = document.querySelector('meta[property="og:title"]');
      if (metaTitle) metaTitle.setAttribute('content', product.name);

      const metaImg = document.querySelector('meta[property="og:image"]');
      if (metaImg) metaImg.setAttribute('content', product.image);

      const metaPrice = document.querySelector('meta[property="product:price:amount"]');
      if (metaPrice) metaPrice.setAttribute('content', product.price.toString());
    }
  }, [product]);

  if (!product) return (
    <div className="p-10 text-center">
        <h2 className="text-xl font-bold">Mahsulot topilmadi</h2>
        <button onClick={() => navigate('/menu')} className="mt-4 text-red-600 font-bold">Menyuga qaytish</button>
    </div>
  );

  const handleAddToCart = () => {
    addToCart(product, quantity);
    setAdded(true);
    setTimeout(() => setAdded(false), 2000);
  };

  const nextImage = () => {
    setActiveImageIndex((prev) => (prev + 1) % allImages.length);
  };

  const prevImage = () => {
    setActiveImageIndex((prev) => (prev - 1 + allImages.length) % allImages.length);
  };

  return (
    <div className="bg-white min-h-screen">
      {/* Mobile Image Gallery */}
      <div className="relative w-full aspect-[4/3] bg-slate-100 lg:hidden group">
        <div className="w-full h-full overflow-hidden">
             <img 
                src={allImages[activeImageIndex]} 
                alt={product.name} 
                className="w-full h-full object-cover transition-opacity duration-500" 
             />
        </div>

        <button 
          onClick={() => navigate(-1)} 
          className="absolute top-4 left-4 z-20 w-10 h-10 bg-white/80 backdrop-blur rounded-full flex items-center justify-center text-slate-900 shadow-lg"
        >
          <ChevronLeft size={24} />
        </button>

        {allImages.length > 1 && (
            <>
                <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-1.5 z-10">
                    {allImages.map((_, i) => (
                        <div key={i} className={`h-1.5 rounded-full transition-all ${i === activeImageIndex ? 'w-6 bg-red-600' : 'w-1.5 bg-white/50'}`}></div>
                    ))}
                </div>
                <button onClick={prevImage} className="absolute left-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-black/20 text-white rounded-full flex items-center justify-center backdrop-blur-sm"><ChevronLeft size={20}/></button>
                <button onClick={nextImage} className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-black/20 text-white rounded-full flex items-center justify-center backdrop-blur-sm"><ChevronRight size={20}/></button>
            </>
        )}
      </div>

      <div className="max-w-6xl mx-auto px-4 md:px-8 py-6 md:py-12 flex flex-col lg:flex-row gap-12">

        {/* Desktop Gallery */}
        <div className="hidden lg:block flex-1 space-y-4">
            <button onClick={() => navigate(-1)} className="mb-2 flex items-center text-slate-400 font-bold hover:text-red-600 transition-colors uppercase tracking-widest text-[10px]">
                <ChevronLeft size={14} /> Orqaga qaytish
            </button>

            <div className="aspect-square bg-slate-50 rounded-[3rem] overflow-hidden shadow-2xl border border-slate-100 relative group">
                <img 
                    src={allImages[activeImageIndex]} 
                    alt={product.name} 
                    className="w-full h-full object-cover hover:scale-105 transition-all duration-700" 
                />
                {allImages.length > 1 && (
                    <div className="absolute inset-x-4 top-1/2 -translate-y-1/2 flex justify-between opacity-0 group-hover:opacity-100 transition-opacity">
                         <button onClick={prevImage} className="w-12 h-12 bg-white/90 backdrop-blur rounded-full shadow-xl flex items-center justify-center text-slate-900 hover:bg-red-600 hover:text-white transition-all"><ChevronLeft size={24}/></button>
                         <button onClick={nextImage} className="w-12 h-12 bg-white/90 backdrop-blur rounded-full shadow-xl flex items-center justify-center text-slate-900 hover:bg-red-600 hover:text-white transition-all"><ChevronRight size={24}/></button>
                    </div>
                )}
            </div>

            {/* Thumbnails */}
            {allImages.length > 1 && (
                <div className="flex gap-4 justify-center">
                    {allImages.map((img, i) => (
                        <button 
                            key={i} 
                            onClick={() => setActiveImageIndex(i)}
                            className={`w-20 h-20 rounded-2xl overflow-hidden border-4 transition-all ${i === activeImageIndex ? 'border-red-600 shadow-lg' : 'border-transparent opacity-60 hover:opacity-100'}`}
                        >
                            <img src={img} className="w-full h-full object-cover" />
                        </button>
                    ))}
                </div>
            )}
        </div>

        {/* Content Area */}
        <div className="flex-1 space-y-8">
            <div>
                <span className="text-red-600 font-black text-[10px] uppercase tracking-[0.3em] mb-2 block">{product.category}</span>
                <h1 className="text-4xl md:text-5xl font-black text-slate-900 italic uppercase tracking-tighter leading-none">{product.name}</h1>
                <p className="mt-4 text-slate-500 font-medium leading-relaxed max-w-lg">{product.description}</p>
            </div>

            {/* Nutritional Info */}
            <div className="flex gap-4">
                <div className="flex-1 bg-slate-50 p-4 rounded-3xl flex items-center gap-3 border border-slate-100">
                    <div className="w-10 h-10 bg-orange-100 text-orange-600 rounded-2xl flex items-center justify-center shrink-0"><Flame size={20}/></div>
                    <div>
                        <span className="text-[10px] font-black text-slate-400 uppercase block tracking-widest">Kaloriya</span>
                        <span className="font-black text-slate-900 uppercase">245 kkal</span>
                    </div>
                </div>
                <div className="flex-1 bg-slate-50 p-4 rounded-3xl flex items-center gap-3 border border-slate-100">
                    <div className="w-10 h-10 bg-blue-100 text-blue-600 rounded-2xl flex items-center justify-center shrink-0"><Scale size={20}/></div>
                    <div>
                        <span className="text-[10px] font-black text-slate-400 uppercase block tracking-widest">Og'irligi</span>
                        <span className="font-black text-slate-900 uppercase">220 gr</span>
                    </div>
                </div>
            </div>

            {/* Price & Quantity */}
            <div className="flex items-end justify-between py-6 border-y border-slate-100">
                <div>
                    <span className="text-xs font-black text-slate-400 uppercase tracking-widest block mb-1">Narxi</span>
                    <span className="text-4xl font-black text-red-600 italic tracking-tighter">{formatCurrency(product.price)}</span>
                </div>

                <div className="flex items-center bg-slate-100 p-2 rounded-2xl gap-2">
                    <button 
                        onClick={() => setQuantity(q => Math.max(1, q - 1))}
                        className="w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center text-slate-400 hover:text-red-600 transition-colors"
                    >
                        <Minus size={20} />
                    </button>
                    <span className="w-10 text-center font-black text-xl">{quantity}</span>
                    <button 
                        onClick={() => setQuantity(q => q + 1)}
                        className="w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center text-slate-400 hover:text-red-600 transition-colors"
                    >
                        <Plus size={20} />
                    </button>
                </div>
            </div>

            {/* Actions */}
            <div className="flex gap-4">
                <button 
                    onClick={handleAddToCart}
                    className={`flex-1 py-5 rounded-2xl font-black text-xl uppercase italic tracking-tighter shadow-xl transition-all active:scale-95 flex items-center justify-center gap-3 ${added ? 'bg-green-600 text-white shadow-green-200' : 'bg-red-600 text-white shadow-red-200 hover:bg-red-700'}`}
                >
                    {added ? 'Savatga qo\'shildi!' : <><ShoppingBag size={24} /> Savatga qo'shish</>}
                </button>
            </div>

            <div className="bg-slate-50 p-4 rounded-3xl border border-slate-100 flex items-start gap-4">
                <Info className="text-slate-400 shrink-0 mt-1" size={20} />
                <p className="text-xs text-slate-400 font-bold uppercase tracking-wider leading-relaxed">
                    Tarkibi: Tovuq go'shti, bug'doy unidan yopilgan bulochka, maxsus "Sezar" sousi, aysberg salati va yangi pomidorlar.
                </p>
            </div>
        </div>
      </div>
    </div>
  );
};

export default ProductDetail;

import React, { useState } from 'react';
import { useMenu } from '../../context/MenuContext';
import { Product } from '../../types';
import { Plus, Edit2, Trash2, X, Image as ImageIcon } from 'lucide-react';
import { formatCurrency } from '../../utils/format';

const AdminMenu = () => {
  const { products, addProduct, updateProduct, deleteProduct } = useMenu();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Partial<Product>>({});

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const productData = {
      ...editingProduct,
      price: Number(editingProduct.price),
      id: editingProduct.id || Math.random().toString(36).substr(2, 9),
      popular: editingProduct.popular || false,
    } as Product;

    if (editingProduct.id) {
      updateProduct(productData);
    } else {
      addProduct(productData);
    }
    setIsModalOpen(false);
    setEditingProduct({});
  };

  const openEdit = (product: Product) => {
    setEditingProduct(product);
    setIsModalOpen(true);
  };

  const openNew = () => {
    setEditingProduct({ category: 'burgers', image: '', images: ['', ''] });
    setIsModalOpen(true);
  };

  const handleImageChange = (index: number, val: string) => {
      if (index === 0) {
          setEditingProduct({ ...editingProduct, image: val });
      } else {
          const newImgs = [...(editingProduct.images || ['', ''])];
          newImgs[index - 1] = val;
          setEditingProduct({ ...editingProduct, images: newImgs });
      }
  };

  return (
    <div className="space-y-4 pb-20">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-black text-slate-900">Menu Manager</h2>
        <button 
          onClick={openNew}
          className="bg-red-600 text-white px-4 py-2 rounded-lg font-bold text-sm flex items-center space-x-2"
        >
          <Plus size={16} /> <span>Add Item</span>
        </button>
      </div>

      <div className="space-y-3">
        {products.map(product => (
          <div key={product.id} className="bg-white p-3 rounded-xl shadow-sm border border-slate-100 flex gap-3">
            <div className="w-20 h-20 bg-slate-100 rounded-lg overflow-hidden flex-shrink-0">
              <img src={product.image} alt={product.name} className="w-full h-full object-cover" />
            </div>
            <div className="flex-grow">
              <div className="flex justify-between items-start">
