import { MENU_ITEMS } from '../constants';

const INITIAL_CATEGORIES: Category[] = [
  { id: 'buckets', name: 'Buckets', image: 'https://images.unsplash.com/photo-1513639776629-7b611d22f654?auto=format&fit=crop&q=80&w=400' },
