  { id: 'chicken', name: 'Chicken', image: 'https://images.unsplash.com/photo-1626700051175-6818013e1d4f?auto=format&fit=crop&q=80&w=400' },
  { id: 'snacks', name: 'Snacks', image: 'https://images.unsplash.com/photo-1573080496987-aeb4d9170d5c?auto=format&fit=crop&q=80&w=400' },
  { id: 'drinks', name: 'Drinks', image: 'https://images.unsplash.com/photo-1622483767028-3f66f32aef97?auto=format&fit=crop&q=80&w=400' }
];

interface MenuContextType {
  products: Product[];
  categories: Category[];
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;
  getProduct: (id: string) => Product | undefined;
  addCategory: (category: Category) => void;
  updateCategory: (category: Category) => void;
  deleteCategory: (id: string) => void;
}

const MenuContext = createContext<MenuContextType | undefined>(undefined);

export const MenuProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('kfc_menu');
    return saved ? JSON.parse(saved) : MENU_ITEMS;
  });

  const [categories, setCategories] = useState<Category[]>(() => {
    const saved = localStorage.getItem('kfc_categories');
    return saved ? JSON.parse(saved) : INITIAL_CATEGORIES;
  });

  useEffect(() => {
    localStorage.setItem('kfc_menu', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('kfc_categories', JSON.stringify(categories));
  }, [categories]);

  const addProduct = (product: Product) => setProducts(prev => [...prev, product]);
  const updateProduct = (product: Product) => setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  const deleteProduct = (id: string) => setProducts(prev => prev.filter(p => p.id !== id));
  const getProduct = (id: string) => products.find(p => p.id === id);

  const addCategory = (category: Category) => setCategories(prev => [...prev, category]);
  const updateCategory = (category: Category) => setCategories(prev => prev.map(c => c.id === category.id ? category : c));
  const deleteCategory = (id: string) => {
    if (products.some(p => p.category === id)) {
      alert("Bu kategoriyada mahsulotlar bor. Avval ularni o'chiring yoki boshqa kategoriyaga o'tkazing.");
      return;
    }
    setCategories(prev => prev.filter(c => c.id !== id));
  };

  return (
    <MenuContext.Provider value={{ 
      products, categories, addProduct, updateProduct, deleteProduct, getProduct,
      addCategory, updateCategory, deleteCategory 
    }}>
      {children}
    </MenuContext.Provider>
  );
};

export const useMenu = () => {
  const context = useContext(MenuContext);
  if (!context) throw new Error('useMenu must be used within MenuProvider');
  return context;
};

