              <div className="flex-grow">
                <div className="flex justify-between items-start">
                  <h3 className="font-bold text-slate-900">{product.name}</h3>
                  <div className="flex space-x-2">
                    <button onClick={() => openEdit(product)} className="text-blue-600 bg-blue-50 p-1.5 rounded-lg"><Edit2 size={16} /></button>
                    <button onClick={() => deleteProduct(product.id)} className="text-red-600 bg-red-50 p-1.5 rounded-lg"><Trash2 size={16} /></button>
                  </div>
                </div>
                <p className="text-xs text-slate-500 line-clamp-1 mb-1">{product.description}</p>
                <div className="flex justify-between items-center mt-2">
                   <span className="font-bold text-red-600 text-sm">{formatCurrency(product.price)}</span>
                   <span className="text-[10px] bg-slate-100 px-2 py-1 rounded font-bold uppercase text-slate-500">{cat?.name || product.category}</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black/50 p-4 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-2xl p-6 shadow-2xl max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold">{editingProduct.id ? 'Tahrirlash' : 'Yangi mahsulot'}</h3>
              <button onClick={() => setIsModalOpen(false)}><X className="text-slate-400" /></button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nomi</label>
                <input 
                  required
                  value={editingProduct.name || ''} 
                  onChange={e => setEditingProduct({...editingProduct, name: e.target.value})}
                  className="w-full p-3 border border-slate-200 rounded-xl"
                />
              </div>

              <div className="flex gap-4">
                <div className="flex-1">
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Narxi (so'm)</label>
                  <input 
                    required
                    type="number"
                    value={editingProduct.price || ''} 
                    onChange={e => setEditingProduct({...editingProduct, price: Number(e.target.value)})}
                    className="w-full p-3 border border-slate-200 rounded-xl"
                  />
                </div>
                <div className="flex-1">
                   <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Kategoriya</label>
                   <select 
                      value={editingProduct.category || ''}
                      onChange={e => setEditingProduct({...editingProduct, category: e.target.value})}
                      className="w-full p-3 border border-slate-200 rounded-xl bg-white"
                   >
                     {categories.map(c => (
                       <option key={c.id} value={c.id}>{c.name}</option>
                     ))}
                   </select>
                </div>
              </div>

              <div className="space-y-2">
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Rasmlar (3 tagacha)</label>
                {[0, 1, 2].map((idx) => (
                    <div key={idx} className="flex gap-2 items-center">
                        <span className="text-[10px] font-black text-slate-300 w-4">{idx + 1}</span>
                        <input 
                            required={idx === 0}
                            value={idx === 0 ? (editingProduct.image || '') : (editingProduct.images?.[idx - 1] || '')} 
                            onChange={e => handleImageChange(idx, e.target.value)}
                            className="flex-1 p-2.5 border border-slate-200 rounded-xl text-sm"
                            placeholder={idx === 0 ? "Asosiy rasm URL" : "Qo'shimcha rasm URL (ixtiyoriy)"}
                        />
                    </div>
                ))}
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Tavsif</label>
                <textarea 
                  required
                  value={editingProduct.description || ''} 
                  onChange={e => setEditingProduct({...editingProduct, description: e.target.value})}
                  className="w-full p-3 border border-slate-200 rounded-xl h-24"
                />
              </div>

              <div className="flex items-center space-x-2">
                <input 
                  type="checkbox"
                  id="popular"
                  checked={editingProduct.popular || false}
                  onChange={e => setEditingProduct({...editingProduct, popular: e.target.checked})}
                  className="w-5 h-5 accent-red-600 rounded"
                />
                <label htmlFor="popular" className="font-medium text-slate-700">Xit mahsulot sifatida belgilash</label>
              </div>

              <button type="submit" className="w-full bg-red-600 text-white py-3 rounded-xl font-bold text-lg mt-4">
                Saqlash
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

