import { initializeApp } from 'firebase/app';
import { getFirestore, collection, getDocs, addDoc, updateDoc, deleteDoc, doc, setDoc, onSnapshot, query, orderBy } from 'firebase/firestore';

// DIQQAT: Bu yerda o'zingizning Firebase konfiguratsiyangizni qo'shishingiz kerak.
// console.firebase.google.com dan loyiha oching.
const firebaseConfig = {
  apiKey: "YOUR_API_KEY",
  authDomain: "your-app.firebaseapp.com",
  projectId: "your-app",
  storageBucket: "your-app.appspot.com",
  messagingSenderId: "123456789",
  appId: "1:123456789:web:abcdef"
};

let db: any = null;

try {
    // Agar API_KEY o'rnatilmagan bo'lsa, xatolik bermasligi uchun tekshiramiz
    if (firebaseConfig.apiKey !== "YOUR_API_KEY") {
        const app = initializeApp(firebaseConfig);
        db = getFirestore(app);
    }
} catch (e) {
    console.warn("Firebase ulanishda xatolik:", e);
}

// Ma'lumotlarni boshqarish uchun generic xizmatlar
export const dbService = {
  // To'plamni (collection) olish
  async getCollection(colName: string) {
    if (!db) return JSON.parse(localStorage.getItem(`kfc_${colName}`) || '[]');
    const q = query(collection(db, colName));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
  },

  // Real-vaqtda kuzatish (barcha mijozlar uchun dinamik yangilanish)
  subscribe(colName: string, callback: (data: any[]) => void) {
    if (!db) return () => {};
    const q = query(collection(db, colName));
    return onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      callback(data);
    });
  },

  // Hujjat qo'shish yoki o'zgartirish
  async saveItem(colName: string, item: any) {
    if (!db) {
        const current = JSON.parse(localStorage.getItem(`kfc_${colName}`) || '[]');
        const exists = current.findIndex((i: any) => i.id === item.id);
        if (exists > -1) current[exists] = item;
        else current.push(item);
        localStorage.setItem(`kfc_${colName}`, JSON.stringify(current));
        return item.id;
    }

    if (item.id && item.id.length > 5) {
        await setDoc(doc(db, colName, item.id), item, { merge: true });
        return item.id;
    } else {
        const docRef = await addDoc(collection(db, colName), item);
        return docRef.id;
    }
  },

  // O'chirish
  async deleteItem(colName: string, id: string) {
    if (!db) {
        const current = JSON.parse(localStorage.getItem(`kfc_${colName}`) || '[]');
        const filtered = current.filter((i: any) => i.id !== id);
        localStorage.setItem(`kfc_${colName}`, JSON.stringify(filtered));
        return;
    }
    await deleteDoc(doc(db, colName, id));
  }
};

