  updateCategory: (category: Category) => void;
  deleteCategory: (id: string) => void;
}

const MenuContext = createContext<MenuContextType | undefined>(undefined);

export const MenuProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);

  // Real-vaqtda bazani kuzatish
  useEffect(() => {
    // Agar baza bo'sh bo'lsa, default ma'lumotlarni yuklab qo'yamiz (faqat birinchi marta)
    const init = async () => {
        const cloudProducts = await dbService.getCollection('menu');
        const cloudCats = await dbService.getCollection('categories');

        if (cloudProducts.length === 0) {
            MENU_ITEMS.forEach(item => dbService.saveItem('menu', item));
        }
        if (cloudCats.length === 0) {
            INITIAL_CATEGORIES.forEach(cat => dbService.saveItem('categories', cat));
        }
    };
    init();

    // Kuzatishni boshlash
    const unsubMenu = dbService.subscribe('menu', (data) => setProducts(data));
    const unsubCats = dbService.subscribe('categories', (data) => setCategories(data));

    return () => {
        unsubMenu();
        unsubCats();
    };
  }, []);

  const addProduct = (product: Product) => dbService.saveItem('menu', product);
  const updateProduct = (product: Product) => dbService.saveItem('menu', product);
  const deleteProduct = (id: string) => dbService.deleteItem('menu', id);
  const getProduct = (id: string) => products.find(p => p.id === id);

  const addCategory = (category: Category) => dbService.saveItem('categories', category);
  const updateCategory = (category: Category) => dbService.saveItem('categories', category);
  const deleteCategory = (id: string) => {
    if (products.some(p => p.category === id)) {
      alert("Bu kategoriyada mahsulotlar bor. Avval ularni o'chiring.");
      return;
    }
    dbService.deleteItem('categories', id);
  };

  return (
    <MenuContext.Provider value={{ 
      products, categories, addProduct, updateProduct, deleteProduct, getProduct,
      addCategory, updateCategory, deleteCategory 
    }}>
      {children}
    </MenuContext.Provider>
  );
};

export const useMenu = () => {
  const context = useContext(MenuContext);
  if (!context) throw new Error('useMenu must be used within MenuProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Order, CartItem } from '../types';
import { formatCurrency } from '../utils/format';
import { dbService } from '../lib/db';

const TG_BOT_TOKEN = 'YOUR_BOT_TOKEN'; 
const TG_CHAT_ID = 'YOUR_CHAT_ID';     

interface OrderContextType {
  orders: Order[];
  placeOrder: (items: CartItem[], total: number, address: string, phone: string, userName: string, paymentMethod: string) => void;
  updateOrderStatus: (orderId: string, status: Order['status']) => void;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [orders, setOrders] = useState<Order[]>([]);

  useEffect(() => {
    const unsub = dbService.subscribe('orders', (data) => {
        // Buyurtmalarni vaqti bo'yicha tartiblaymiz (eng yangisi tepada)
        const sorted = data.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        setOrders(sorted);
    });
    return () => unsub();
  }, []);

  const sendTelegramNotification = async (order: Order) => {
    if (!TG_BOT_TOKEN || TG_BOT_TOKEN === 'YOUR_BOT_TOKEN') return;

    const itemsList = order.items
      .map(i => `- ${i.name} (${i.quantity} x ${formatCurrency(i.price)})`)
      .join('\n');

    const message = `
🍗 <b>Yangi Buyurtma!</b> #${order.id}
👤 <b>Mijoz:</b> ${order.userName || 'Mehmon'}
📞 <b>Tel:</b> ${order.phone}
📍 <b>Manzil:</b> ${order.address}
💳 <b>To'lov:</b> ${order.paymentMethod}
🛒 <b>Tarkibi:</b>\n${itemsList}
💰 <b>Jami:</b> ${formatCurrency(order.total)}
    `;

    try {
      const url = `https://api.telegram.org/bot${TG_BOT_TOKEN}/sendMessage?chat_id=${TG_CHAT_ID}&text=${encodeURIComponent(message)}&parse_mode=HTML`;
      await fetch(url, { method: 'GET', mode: 'no-cors' });
    } catch (e) {}
  };

  const placeOrder = (items: CartItem[], total: number, address: string, phone: string, userName: string, paymentMethod: string) => {
    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 6).toUpperCase(),
      items,
      total,
      status: 'new',
      date: new Date().toISOString(),
      address,
      phone,
      paymentMethod,
      userName
    }; 

    dbService.saveItem('orders', newOrder);
    sendTelegramNotification(newOrder);
  };

  const updateOrderStatus = (orderId: string, status: Order['status']) => {
    const order = orders.find(o => o.id === orderId);
    if (order) {
        dbService.saveItem('orders', { ...order, status });
    }
  };

  return (
    <OrderContext.Provider value={{ orders, placeOrder, updateOrderStatus }}>
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error('useOrders must be used within OrderProvider');
  return context;
};

