export const dbService = {
  async getCollection(colName: string) {
    if (!db) return JSON.parse(localStorage.getItem(`kfc_${colName}`) || '[]');
    try {
        const q = query(collection(db, colName));
        const querySnapshot = await getDocs(q);
        return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
    } catch (e) {
        console.error(`${colName} olishda xato:`, e);
        return [];
    }
  },

  subscribe(colName: string, callback: (data: any[]) => void) {
    if (!db) return () => {};
    const q = query(collection(db, colName));
    return onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      callback(data);
    }, (error) => {
      console.error(`${colName} subscribe xatosi:`, error);
    });
  },

  async saveItem(colName: string, item: any) {
    if (!db) {
        const current = JSON.parse(localStorage.getItem(`kfc_${colName}`) || '[]');
        const exists = current.findIndex((i: any) => i.id === item.id);
        if (exists > -1) current[exists] = item;
        else current.push(item);
        localStorage.setItem(`kfc_${colName}`, JSON.stringify(current));
        return item.id;
    }

    try {
        if (item.id && item.id.length > 5) {
            const { id, ...data } = item;
            await setDoc(doc(db, colName, id), data, { merge: true });
            return id;
        } else {
            const docRef = await addDoc(collection(db, colName), item);
            return docRef.id;
        }
    } catch (e) {
        console.error("Saqlashda xato:", e);
        throw e;
    }
  },

  async deleteItem(colName: string, id: string) {
    if (!db) {
        const current = JSON.parse(localStorage.getItem(`kfc_${colName}`) || '[]');
        const filtered = current.filter((i: any) => i.id !== id);
        localStorage.setItem(`kfc_${colName}`, JSON.stringify(filtered));
        return;
    }
    try {
        await deleteDoc(doc(db, colName, id));
    } catch (e) {
        console.error("O'chirishda xato:", e);
    }
  }
};

payload.text:
### Endi eng muhim qadam (Firebase Console-da):

Hozir kod ulandi, lekin baza hali ma'lumotlarni qabul qilmasligi mumkin. Buni to'g'rilash uchun:

1.  [Firebase Console](https://console.firebase.google.com/)-ga qayting.
2.  Chap menyudan **Build** -> **Firestore Database** bo'limiga kiring.
3.  **Create Database** tugmasini bosing.
4.  **Rules** (Qoidalar) tabiga o'ting.
5.  U yerdagi kodni vaqtincha mana bunga almashtiring (test qilish uchun hamma o'qiy olishi uchun):
    ```javascript
    rules_version = '2';
    service cloud.firestore {
      match /databases/{database}/documents {
        match /{document=**} {
          allow read, write: if true;
        }
      }
    }
    ```
6.  **Publish** tugmasini bosing.

**Tayyor!** Endi siz Admin panelda mahsulot qo'shsangiz yoki o'zgartirsangiz, u to'g'ridan-to'g'ri Firebase bazasiga tushadi va hamma foydalanuvchilarda bir vaqtda ko'rinadi.

Firebase Console'dagi qoidalarni (Rules) o'zgartirishda muammo bo'layotgan bo'lsa, bu odatda ikki sababga ko'ra sodir bo'ladi: yoki siz matnni tahrirlagandan so'ng **"Publish"** (Nashr qilish) tugmasini bosmagansiz, yoki Firestore hali to'liq ishga tushmagan.

Siz taqdim etgan rasmdagi qoidalar hozir hamma narsani taqiqlab qo'ygan (`if false`). Uni tahrirlab, quyidagi kodni qo'ying va yuqoridagi ko'k tugmani bosing.

Shuningdek, import map'dagi versiyalarni moslashtirib, kodni biroz mustahkamlab qo'yamiz, shunda xatolik bo'lsa, sizga aniq xabar ko'rinadi.

### 1. Firebase Rules (Qoidalar) bo'limiga mana buni nusxalab qo'ying:
```javascript
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /{document=**} {
      allow read, write: if true;
    }
  }
}
```
*Keyin tepada paydo bo'lgan **"Publish"** tugmasini bosing.*

### 2. Kodni yangilash:
Firebase versiyalarini bir xil (11.3.1) qilish va xatoliklarni yaxshiroq tutish uchun quyidagi o'zgarishlarni bajaramiz.

