import { TrendingUp, ShoppingBag, Package, DollarSign, Database, AlertTriangle, CheckCircle2 } from 'lucide-react';
import { formatCurrency } from '../../utils/format';
import { dbService } from '../../lib/db';

const AdminDashboard = () => {
  const { orders } = useOrders();
  const { products } = useMenu();
  const [dbStatus, setDbStatus] = useState(dbService.getStatus());

  useEffect(() => {
    const interval = setInterval(() => {
        setDbStatus(dbService.getStatus());
    }, 2000);
    return () => clearInterval(interval);
  }, []);

  const totalRevenue = orders.reduce((acc, order) => acc + order.total, 0);
  const activeOrders = orders.filter(o => o.status !== 'completed').length;

  const StatCard = ({ title, value, icon: Icon, color }: any) => (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 flex items-center space-x-4">
      <div className={`w-12 h-12 rounded-full flex items-center justify-center ${color}`}>
        <Icon className="text-white" size={24} />
      </div>
      <div>
        <p className="text-slate-500 text-xs font-bold uppercase">{title}</p>
        <h3 className="text-xl font-black text-slate-900">{value}</h3>
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter">Boshqaruv Paneli</h2>

        {/* Database Status Indicator */}
        <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full border text-[10px] font-black uppercase tracking-widest ${
            dbStatus === 'online' ? 'bg-green-50 border-green-200 text-green-600' : 
            dbStatus === 'error' ? 'bg-red-50 border-red-200 text-red-600' : 'bg-slate-50 border-slate-200 text-slate-400'
        }`}>
            {dbStatus === 'online' ? <CheckCircle2 size={14} /> : <AlertTriangle size={14} />}
            Firestore: {dbStatus === 'online' ? 'Ulandi' : dbStatus === 'error' ? 'Ruxsat yo\'q' : 'Ulanmoqda...'}
        </div>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard 
          title="Jami tushum" 
          value={formatCurrency(totalRevenue)} 
          icon={DollarSign} 
          color="bg-green-500 shadow-lg shadow-green-100" 
        />
        <StatCard 
          title="Buyurtmalar" 
          value={orders.length} 
          icon={ShoppingBag} 
          color="bg-blue-500 shadow-lg shadow-blue-100" 
        />
        <StatCard 
          title="Faol" 
          value={activeOrders} 
          icon={Package} 
          color="bg-orange-500 shadow-lg shadow-orange-100" 
        />
        <StatCard 
          title="Mahsulotlar" 
          value={products.length} 
          icon={TrendingUp} 
          color="bg-purple-500 shadow-lg shadow-purple-100" 
        />
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 p-6">
        <h3 className="font-black text-slate-900 mb-4 uppercase italic tracking-tighter">Oxirgi buyurtmalar</h3>
        <div className="space-y-3">
          {orders.slice(0, 5).map(order => (
            <div key={order.id} className="flex justify-between items-center text-sm border-b border-slate-50 pb-3 last:border-0 last:pb-0">
              <div>
                <span className="font-black text-slate-900 block">#{order.id}</span>
                <span className="text-[10px] text-slate-400 font-bold uppercase">{new Date(order.date).toLocaleString()}</span>
              </div>
              <span className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest ${
                order.status === 'new' ? 'bg-blue-100 text-blue-600' :
                order.status === 'cooking' ? 'bg-orange-100 text-orange-600' :
                order.status === 'delivering' ? 'bg-purple-100 text-purple-600' :
                'bg-green-100 text-green-600'
              }`}>
                {order.status}
              </span>
            </div>
          ))}
          {orders.length === 0 && <p className="text-slate-400 text-sm italic font-medium">Hozircha buyurtmalar yo'q.</p>}
        </div>
      </div>
    </div>
  );
};

