import React, { createContext, useContext, useState, useEffect } from 'react';
import { User } from '../types';
import { BRANCHES, Branch } from '../constants';

interface AuthContextType {
  user: User | null;
  login: (phone: string, name?: string) => void;
  logout: () => void;
  isAdmin: boolean;
  currentAddress: string;
  setCurrentAddress: (address: string) => void;
  orderType: 'delivery' | 'pickup';
  setOrderType: (type: 'delivery' | 'pickup') => void;
  selectedBranch: Branch | null;
  setSelectedBranch: (branch: Branch) => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [currentAddress, setCurrentAddress] = useState<string>("Toshkent, Amir Temur 1");
  const [orderType, setOrderType] = useState<'delivery' | 'pickup'>('delivery');
  const [selectedBranch, setSelectedBranch] = useState<Branch | null>(null);

  useEffect(() => {
    const stored = localStorage.getItem('restoran_user');
    if (stored) {
      setUser(JSON.parse(stored));
    }

    if (window.Telegram?.WebApp) {
        const tg = window.Telegram.WebApp;
        tg.ready();
        tg.expand();
        tg.setHeaderColor('#ffffff');
        tg.setBackgroundColor('#f8fafc');

        const tgUser = tg.initDataUnsafe?.user;
        if (tgUser) {
            const telegramPhone = `+998(TG)${tgUser.id}`;
            const displayName = `${tgUser.first_name} ${tgUser.last_name || ''}`.trim();
            const newUser: User = { phone: telegramPhone, name: displayName, telegramId: tgUser.id };
            setUser(newUser);
            localStorage.setItem('restoran_user', JSON.stringify(newUser));
        }
    }
  }, []);

  const login = (phone: string, name?: string) => {
    const newUser: User = { phone, name: name || 'Restoran Mijozi' };
    setUser(newUser);
    localStorage.setItem('restoran_user', JSON.stringify(newUser));
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('restoran_user');
  };

  const isAdmin = user?.phone === '+998901234567' || user?.phone?.includes('(TG)123456789');

  return (
    <AuthContext.Provider value={{ 
      user, login, logout, isAdmin, currentAddress, setCurrentAddress, orderType, setOrderType,
      selectedBranch, setSelectedBranch 
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within AuthProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { CartItem, Product } from '../types';

interface CartContextType {
  items: CartItem[];
  addToCart: (product: Product, quantity?: number) => void;
  removeFromCart: (productId: string) => void;
  updateQuantity: (productId: string, delta: number) => void;
  clearCart: () => void;
  total: number;
}

const CartContext = createContext<CartContextType | undefined>(undefined);

export const CartProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [items, setItems] = useState<CartItem[]>([]);

  useEffect(() => {
    const stored = localStorage.getItem('restoran_cart');
    if (stored) {
      try {
        setItems(JSON.parse(stored));
      } catch (e) {
        console.error("Cart parse error", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('restoran_cart', JSON.stringify(items));
  }, [items]);

  const addToCart = useCallback((product: Product, quantity = 1) => {
    if (!product || !product.id) return;

    setItems(prev => {
      const existing = prev.find(p => p.id === product.id);
      if (existing) {
        return prev.map(p => p.id === product.id ? { ...p, quantity: p.quantity + Math.max(1, quantity) } : p);
      }
      return [...prev, { ...product, quantity: Math.max(1, quantity) }];
    });
  }, []);

  const removeFromCart = useCallback((productId: string) => {
    setItems(prev => prev.filter(p => p.id !== productId));
  }, []);

  const updateQuantity = useCallback((productId: string, delta: number) => {
    setItems(prev => prev.map(p => {
      if (p.id === productId) {
        const newQty = Math.max(0, p.quantity + delta);
        return { ...p, quantity: newQty };
      }
      return p;
    }).filter(p => p.quantity > 0));
  }, []);

  const clearCart = useCallback(() => setItems([]), []);

  const total = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  return (
    <CartContext.Provider value={{ items, addToCart, removeFromCart, updateQuantity, clearCart, total }}>
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => {
  const context = useContext(CartContext);
  if (!context) throw new Error('useCart must be used within CartProvider');
  return context;
};

