import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useMenu } from '../context/MenuContext';
import { useCart } from '../context/CartContext';
import { formatCurrency } from '../utils/format';
import { ChevronLeft, Plus, Minus, ShoppingBag, Info, Flame, Scale, ChevronRight } from 'lucide-react';

const ProductDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { products, categories } = useMenu();
  const { addToCart } = useCart();
  const [quantity, setQuantity] = useState(1);
  const [added, setAdded] = useState(false);
  const [activeImageIndex, setActiveImageIndex] = useState(0);

  const product = products.find(p => p.id === id);
  const categoryName = categories.find(c => c.id === product?.category)?.name || '';

  // Combine main image and gallery images
  const allImages = product ? [product.image, ...(product.images || [])].filter(Boolean).slice(0, 3) : [];

  useEffect(() => {
    if (product) {
      // SEO Meta Tags update
      document.title = `${product.name} - Restoran Uzbekistan | Onlayn buyurtma`;

      const metaDesc = document.querySelector('meta[name="description"]');
      if (metaDesc) metaDesc.setAttribute('content', `${product.name}: ${product.description}. Restoran Uzbekistan menyusidan buyurtma bering.`);

      // Structured Data (JSON-LD) for Google
      const schemaData = {
        "@context": "https://schema.org/",
        "@type": "Product",
        "name": product.name,
        "image": allImages,
        "description": product.description,
        "brand": {
          "@type": "Brand",
          "name": "Restoran"
        },
        "offers": {
          "@type": "Offer",
          "url": window.location.href,
          "priceCurrency": "UZS",
          "price": product.price,
          "availability": "https://schema.org/InStock"
        }
      };

      const script = document.createElement('script');
      script.type = 'application/ld+json';
      script.text = JSON.stringify(schemaData);
      document.head.appendChild(script);

      return () => {
        document.head.removeChild(script);
      };
    }
  }, [product, allImages]);

  if (!product) return (
    <div className="p-10 text-center">
        <h2 className="text-xl font-bold">Mahsulot topilmadi</h2>
        <button onClick={() => navigate('/menu')} className="mt-4 text-red-600 font-bold underline">Menyuga qaytish</button>
    </div>
  );

  const handleAddToCart = () => {
    addToCart(product, quantity);
    setAdded(true);
    setTimeout(() => setAdded(false), 2000);
  };

  const nextImage = () => setActiveImageIndex((prev) => (prev + 1) % allImages.length);
  const prevImage = () => setActiveImageIndex((prev) => (prev - 1 + allImages.length) % allImages.length);

  return (
    <article className="bg-white min-h-screen">
      {/* Mobile Image Gallery */}
      <section className="relative w-full aspect-[4/3] bg-slate-100 lg:hidden group">
        <div className="w-full h-full overflow-hidden">
             <img 
                src={allImages[activeImageIndex]} 
                alt={`${product.name} - ${activeImageIndex + 1}`} 
                className="w-full h-full object-cover transition-opacity duration-500" 
             />
        </div>
        <button 
          onClick={() => navigate(-1)} 
          className="absolute top-4 left-4 z-20 w-10 h-10 bg-white/80 backdrop-blur rounded-full flex items-center justify-center text-slate-900 shadow-lg"
          aria-label="Orqaga"
        >
          <ChevronLeft size={24} />
        </button>

        {allImages.length > 1 && (
            <>
                <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-1.5 z-10">
                    {allImages.map((_, i) => (
                        <div key={i} className={`h-1.5 rounded-full transition-all ${i === activeImageIndex ? 'w-6 bg-red-600' : 'w-1.5 bg-white/50'}`}></div>
                    ))}
                </div>
                <button onClick={prevImage} className="absolute left-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-black/20 text-white rounded-full flex items-center justify-center backdrop-blur-sm" aria-label="Oldingi rasm"><ChevronLeft size={20}/></button>
                <button onClick={nextImage} className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-black/20 text-white rounded-full flex items-center justify-center backdrop-blur-sm" aria-label="Keyingi rasm"><ChevronRight size={20}/></button>
            </>
        )}
      </section>

      <div className="max-w-6xl mx-auto px-4 md:px-8 py-6 md:py-12 flex flex-col lg:flex-row gap-12">
        {/* Desktop Gallery */}
        <section className="hidden lg:block flex-1 space-y-4">
            <nav aria-label="Breadcrumb">
                <button onClick={() => navigate(-1)} className="mb-2 flex items-center text-slate-400 font-bold hover:text-red-600 transition-colors uppercase tracking-widest text-[10px]">
                    <ChevronLeft size={14} /> Orqaga qaytish
                </button>
            </nav>

            <div className="aspect-square bg-slate-50 rounded-[3rem] overflow-hidden shadow-2xl border border-slate-100 relative group">
                <img 
                    src={allImages[activeImageIndex]} 
                    alt={product.name} 
                    className="w-full h-full object-cover hover:scale-105 transition-all duration-700" 
                />
                {allImages.length > 1 && (
                    <div className="absolute inset-x-4 top-1/2 -translate-y-1/2 flex justify-between opacity-0 group-hover:opacity-100 transition-opacity">
                         <button onClick={prevImage} className="w-12 h-12 bg-white/90 backdrop-blur rounded-full shadow-xl flex items-center justify-center text-slate-900 hover:bg-red-600 hover:text-white transition-all"><ChevronLeft size={24}/></button>
                         <button onClick={nextImage} className="w-12 h-12 bg-white/90 backdrop-blur rounded-full shadow-xl flex items-center justify-center text-slate-900 hover:bg-red-600 hover:text-white transition-all"><ChevronRight size={24}/></button>
                    </div>
                )}
            </div>

            {allImages.length > 1 && (
                <div className="flex gap-4 justify-center">
                    {allImages.map((img, i) => (
                        <button 
                            key={i} 
                            onClick={() => setActiveImageIndex(i)}
                            className={`w-20 h-20 rounded-2xl overflow-hidden border-4 transition-all ${i === activeImageIndex ? 'border-red-600 shadow-lg' : 'border-transparent opacity-60 hover:opacity-100'}`}
                        >
                            <img src={img} alt={`Thumbnail ${i + 1}`} className="w-full h-full object-cover" />
                        </button>
                    ))}
                </div>
            )}
        </section>

        {/* Content Area */}
        <section className="flex-1 space-y-8">
            <header>
                <span className="text-red-600 font-black text-[10px] uppercase tracking-[0.3em] mb-2 block">{categoryName}</span>
                <h1 className="text-4xl md:text-5xl font-black text-slate-900 italic uppercase tracking-tighter leading-none">{product.name}</h1>
                <p className="mt-4 text-slate-500 font-medium leading-relaxed max-w-lg">{product.description}</p>
            </header>

            {/* Nutritional Info */}
            <div className="flex gap-4">
                <div className="flex-1 bg-slate-50 p-4 rounded-3xl flex items-center gap-3 border border-slate-100">
                    <div className="w-10 h-10 bg-orange-100 text-orange-600 rounded-2xl flex items-center justify-center shrink-0"><Flame size={20}/></div>
                    <div>
                        <span className="text-[10px] font-black text-slate-400 uppercase block tracking-widest">Kaloriya</span>
                        <span className="font-black text-slate-900 uppercase">245 kkal</span>
                    </div>
                </div>
                <div className="flex-1 bg-slate-50 p-4 rounded-3xl flex items-center gap-3 border border-slate-100">
                    <div className="w-10 h-10 bg-blue-100 text-blue-600 rounded-2xl flex items-center justify-center shrink-0"><Scale size={20}/></div>
                    <div>
                        <span className="text-[10px] font-black text-slate-400 uppercase block tracking-widest">Og'irligi</span>
                        <span className="font-black text-slate-900 uppercase">220 gr</span>
                    </div>
                </div>
            </div>

            <div className="flex items-end justify-between py-6 border-y border-slate-100">
                <div>
                    <span className="text-xs font-black text-slate-400 uppercase tracking-widest block mb-1">Narxi</span>
                    <span className="text-4xl font-black text-red-600 italic tracking-tighter">{formatCurrency(product.price)}</span>
                </div>

                <div className="flex items-center bg-slate-100 p-2 rounded-2xl gap-2">
                    <button onClick={() => setQuantity(q => Math.max(1, q - 1))} className="w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center text-slate-400 hover:text-red-600 transition-colors" aria-label="Kamaytirish"><Minus size={20} /></button>
                    <span className="w-10 text-center font-black text-xl">{quantity}</span>
                    <button onClick={() => setQuantity(q => q + 1)} className="w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center text-slate-400 hover:text-red-600 transition-colors" aria-label="Ko'paytirish"><Plus size={20} /></button>
                </div>
            </div>

            <button 
                onClick={handleAddToCart}
                className={`w-full py-5 rounded-2xl font-black text-xl uppercase italic tracking-tighter shadow-xl transition-all active:scale-95 flex items-center justify-center gap-3 ${added ? 'bg-green-600 text-white shadow-green-200' : 'bg-red-600 text-white shadow-red-200 hover:bg-red-700'}`}
            >
                {added ? 'Savatga qo\'shildi!' : <><ShoppingBag size={24} /> Savatga qo'shish</>}
            </button>

            <footer className="bg-slate-50 p-4 rounded-3xl border border-slate-100 flex items-start gap-4">
                <Info className="text-slate-400 shrink-0 mt-1" size={20} />
                <p className="text-xs text-slate-400 font-bold uppercase tracking-wider leading-relaxed">
                    Tarkibi: Tovuq go'shti, bug'doy unidan yopilgan bulochka, maxsus "Sezar" sousi, aysberg salati va yangi pomidorlar.
                </p>
            </footer>
        </section>
      </div>
    </article>
  );
};

export default ProductDetail;

