let db: Firestore | null = null;
let connectionStatus: 'connecting' | 'online' | 'error' | 'offline' = 'connecting';

const initFirestore = (): Firestore | null => {
  if (db) return db;
  try {
    const app = getApps().length > 0 ? getApp() : initializeApp(firebaseConfig);
    db = getFirestore(app);
    connectionStatus = 'online';
    return db;
  } catch (e: any) {
    connectionStatus = 'error';
    if (e.message?.includes('Service firestore is not available')) {
        db = null; 
    }
    return null;
  }
};

initFirestore();

const handleFirestoreError = (error: any) => {
  if (error.code === 'permission-denied') {
    connectionStatus = 'error';
    console.warn("⚠️ Firestore ruxsati rad etildi (Permission Denied). Ilova mahalliy xotirada (Local Storage) ishlamoqda. Firebase konsolida qoidalarni tekshiring.");
  } else {
    console.warn("⚠️ Firestore ogohlantirishi:", error.message || error);
  }

  if (error.message?.includes('firestore is not available') || error.message?.includes('Service firestore is not available')) {
    db = null;
    connectionStatus = 'error';
  }
};

export const dbService = {
  getStatus() {
    return connectionStatus;
  },

  async getCollection(colName: string) {
    const localData = JSON.parse(localStorage.getItem(`restoran_${colName}`) || '[]');
    const currentDb = initFirestore();

    if (!currentDb) return localData;

    try {
      const q = query(collection(currentDb, colName));
      const querySnapshot = await getDocs(q);
      const data = querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      // Sinxronizatsiya
      localStorage.setItem(`restoran_${colName}`, JSON.stringify(data));
      return data;
    } catch (e) {
      handleFirestoreError(e);
      return localData; // Xatolik bo'lsa mahalliy datani qaytaramiz
    }
  },

  subscribe(colName: string, callback: (data: any[]) => void) {
    // 1. Darhol mahalliy ma'lumotlarni yuboramiz
    const localData = JSON.parse(localStorage.getItem(`restoran_${colName}`) || '[]');
    callback(localData);

    // 2. Oflayn ishlash uchun lokal event listener
    const localSyncHandler = (e: Event) => {
       const customEvent = e as CustomEvent;
       if (customEvent.detail === colName && connectionStatus === 'error') {
           callback(JSON.parse(localStorage.getItem(`restoran_${colName}`) || '[]'));
       }
    };
    window.addEventListener('restoran_db_update', localSyncHandler);

    const currentDb = initFirestore();
    if (!currentDb) return () => window.removeEventListener('restoran_db_update', localSyncHandler);

    try {
      const q = query(collection(currentDb, colName));
      const unsub = onSnapshot(q, (snapshot) => {
        connectionStatus = 'online';
        const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        localStorage.setItem(`restoran_${colName}`, JSON.stringify(data));
        callback(data);
      }, (error) => {
        handleFirestoreError(error);
      });

      return () => {
          unsub();
          window.removeEventListener('restoran_db_update', localSyncHandler);
      };
    } catch (e) {
      handleFirestoreError(e);
      return () => window.removeEventListener('restoran_db_update', localSyncHandler);
    }
  },

  async saveItem(colName: string, item: any) {
    // Har doim avval mahalliy xotiraga saqlaymiz
    const current = JSON.parse(localStorage.getItem(`restoran_${colName}`) || '[]');
    const exists = current.findIndex((i: any) => i.id === item.id);
    if (exists > -1) current[exists] = item;
    else current.push(item);
    localStorage.setItem(`restoran_${colName}`, JSON.stringify(current));

    // UI ni yangilash uchun lokal event
    window.dispatchEvent(new CustomEvent('restoran_db_update', { detail: colName }));

    const currentDb = initFirestore();
    if (!currentDb) return item.id;

    try {
      if (item.id && item.id.length > 5) {
        const { id, ...data } = item;
        await setDoc(doc(currentDb, colName, id), data, { merge: true });
        return id;
      } else {
        const docRef = await addDoc(collection(currentDb, colName), item);
        return docRef.id;
      }
    } catch (e) {
      handleFirestoreError(e);
      // throw e; olib tashlandi, shunda ilova qotib qolmaydi
      return item.id || Date.now().toString();
    }
  },

  async deleteItem(colName: string, id: string) {
    const current = JSON.parse(localStorage.getItem(`restoran_${colName}`) || '[]');
    const filtered = current.filter((i: any) => i.id !== id);
    localStorage.setItem(`restoran_${colName}`, JSON.stringify(filtered));

    window.dispatchEvent(new CustomEvent('restoran_db_update', { detail: colName }));

    const currentDb = initFirestore();
    if (!currentDb) return;

    try {
      await deleteDoc(doc(currentDb, colName, id));
    } catch (e) {
      handleFirestoreError(e);
    }
  }
};

