const Layout = () => {
  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    const tg = window.Telegram?.WebApp;
    // Telegram muhitida ekanligini tasdiqlash uchun
    if (tg && tg.initData) {
      tg.ready();
      tg.expand();

      const handleBack = () => {
        navigate(-1);
      };

      // Asosiy sahifalarda orqaga tugmasini yashirish, qolganlarida ko'rsatish
      if (location.pathname !== '/' && location.pathname !== '/admin') {
        tg.BackButton.show();
        tg.BackButton.onClick(handleBack);
      } else {
        tg.BackButton.hide();
      }

      return () => {
        tg.BackButton.offClick(handleBack);
      };
    }
  }, [location.pathname, navigate]);

  return (
    <div className="min-h-screen bg-slate-50 lg:flex text-slate-900">
      <Sidebar />
      <main className="flex-1 flex flex-col min-w-0 relative" role="main">
        <div className="flex-1 pb-20 lg:pb-0 overflow-x-hidden">
             <Outlet />
        </div>
        <BottomNav />
        <LiveAgent />
      </main>
    </div>
  );
};

const App = () => {
  return (
    <LanguageProvider>
      <AuthProvider>
        <MenuProvider>
          <OrderProvider>
            <CartProvider>
              <HashRouter>
                <Routes>
                  {/* Public App */}
                  <Route path="/" element={<Layout />}>
                    <Route index element={<Home />} />
                    <Route path="menu" element={<Menu />} />
                    <Route path="product/:id" element={<ProductDetail />} />
                    <Route path="cart" element={<Cart />} />
                    <Route path="profile" element={<Profile />} />
                  </Route>

                  {/* Admin Panel */}
                  <Route path="/admin" element={<AdminLayout />}>
                    <Route index element={<AdminDashboard />} />
                    <Route path="dashboard" element={<AdminDashboard />} />
                    <Route path="categories" element={<AdminCategories />} />
                    <Route path="menu" element={<AdminMenu />} />
                    <Route path="orders" element={<AdminOrders />} />
                    <Route path="knowledge-base" element={<AdminKnowledgeBase />} />
                    <Route path="feed" element={<AdminFeed />} />
                  </Route>
                </Routes>
              </HashRouter>
            </CartProvider>
