        tg.MainButton.text = `${paymentMethod === 'paynet' ? 'PAYNET' : t.checkout.toUpperCase()} - ${formatCurrency(total - discount)}`;
        tg.MainButton.color = '#E4002B'; // Red-600 color
        tg.MainButton.textColor = '#ffffff';

        if (!loading) tg.MainButton.show();

        const onClick = () => handleCheckoutRef.current();
        tg.MainButton.onClick(onClick);

        if (loading) {
          tg.MainButton.showProgress(false);
        } else {
          tg.MainButton.hideProgress();
        }

        return () => {
          tg.MainButton.offClick(onClick);
          tg.MainButton.hide();
        };
