let connectionStatus: 'connecting' | 'online' | 'error' | 'offline' = 'offline';

export const dbService = {
  getStatus(): string {
    return connectionStatus;
  },

  async getCollection(colName: string) {
    const localData = JSON.parse(localStorage.getItem(`restoran_${colName}`) || '[]');
    return localData;
  },

  subscribe(colName: string, callback: (data: any[]) => void) {
    const localData = JSON.parse(localStorage.getItem(`restoran_${colName}`) || '[]');
    callback(localData);

    const localSyncHandler = (e: Event) => {
       const customEvent = e as CustomEvent;
       if (customEvent.detail === colName) {
           callback(JSON.parse(localStorage.getItem(`restoran_${colName}`) || '[]'));
       }
    };
    window.addEventListener('restoran_db_update', localSyncHandler);

    return () => {
        window.removeEventListener('restoran_db_update', localSyncHandler);
    };
  },

  async saveItem(colName: string, item: any) {
    const current = JSON.parse(localStorage.getItem(`restoran_${colName}`) || '[]');
    const exists = current.findIndex((i: any) => i.id === item.id);
    if (exists > -1) current[exists] = item;
    else current.push(item);
    localStorage.setItem(`restoran_${colName}`, JSON.stringify(current));

    window.dispatchEvent(new CustomEvent('restoran_db_update', { detail: colName }));

    return item.id || Date.now().toString();
  },

  async deleteItem(colName: string, id: string) {
    const current = JSON.parse(localStorage.getItem(`restoran_${colName}`) || '[]');
    const filtered = current.filter((i: any) => i.id !== id);
    localStorage.setItem(`restoran_${colName}`, JSON.stringify(filtered));

    window.dispatchEvent(new CustomEvent('restoran_db_update', { detail: colName }));
  }
};

