import React, { createContext, useContext, useState, useEffect } from 'react';
import { Order, CartItem } from '../types';
import { formatCurrency } from '../utils/format';
import { dbService } from '../lib/db';

// XAVFSIZLIK: Token va ID'lar endi muhit o'zgaruvchilaridan olinadi (Frontendda ochiq qolmaydi)
const TG_BOT_TOKEN = process.env.TG_BOT_TOKEN || ''; 
const TG_CHAT_ID = process.env.TG_CHAT_ID || '';     

interface OrderContextType {
  orders: Order[];
  placeOrder: (items: CartItem[], clientTotal: number, discount: number, address: string, phone: string, userName: string, paymentMethod: string) => Promise<void>;
  updateOrderStatus: (orderId: string, status: Order['status']) => void;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [orders, setOrders] = useState<Order[]>([]);

  useEffect(() => {
    const unsub = dbService.subscribe('orders', (data) => {
        const sorted = data.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        setOrders(sorted);
    });
    return () => unsub();
  }, []);

  const sendTelegramNotification = async (order: Order) => {
    if (!TG_BOT_TOKEN) {
        console.warn("Backend: Telegram bot token .env da ko'rsatilmagan. Xabarnoma yuborilmadi.");
        return;
    }

    const itemsList = order.items
      .map(i => `- ${i.name} (${i.quantity} x ${formatCurrency(i.price)})`)
      .join('\n');

    const message = `
🍗 <b>Yangi Buyurtma!</b> #${order.id}
👤 <b>Mijoz:</b> ${order.userName || 'Mehmon'}
📞 <b>Tel:</b> ${order.phone}
📍 <b>Manzil:</b> ${order.address}
💳 <b>To'lov:</b> ${order.paymentMethod}

🛒 <b>Tarkibi:</b>\n${itemsList}

💰 <b>Jami:</b> ${formatCurrency(order.total)}
    `;

    // Deep Linking: Telegramdan to'g'ridan-to'g'ri Web App ga yo'naltirish URL'lari
    const baseUrl = window.location.origin + window.location.pathname;
    const adminUrl = `${baseUrl}#/admin/orders`;

    try {
      const url = `https://api.telegram.org/bot${TG_BOT_TOKEN}/sendMessage`;
      await fetch(url, { 
          method: 'POST', 
          headers: {
              'Content-Type': 'application/json'
          },
          body: JSON.stringify({
              chat_id: TG_CHAT_ID,
              text: message,
              parse_mode: 'HTML',
              reply_markup: {
                  inline_keyboard: [
                      [
                          { text: "🍳 Pishirilmoqda", url: `${adminUrl}?orderId=${order.id}&setStatus=cooking` },
                          { text: "🚚 Yetkazish", url: `${adminUrl}?orderId=${order.id}&setStatus=delivering` }
                      ],
                      [
                          { text: "✅ Yakunlash", url: `${adminUrl}?orderId=${order.id}&setStatus=completed` }
                      ]
                  ]
              }
          })
      });
    } catch (e) {
      console.error("Backend Error: Telegram xabarnoma yuborishda xatolik yuz berdi", e);
    }
  };

  const placeOrder = async (items: CartItem[], clientTotal: number, discount: number, address: string, phone: string, userName: string, paymentMethod: string) => {
    const dbMenu = await dbService.getCollection('menu');

    let secureTotal = 0;
    const verifiedItems = items.map(clientItem => {
        const realItem = dbMenu.find((m: any) => m.id === clientItem.id);
        if (realItem) {
            secureTotal += realItem.price * clientItem.quantity;
            return { ...clientItem, price: realItem.price };
        }
        return clientItem;
    });

    const finalSecureTotal = Math.max(0, secureTotal - discount);

    if (finalSecureTotal !== clientTotal) {
        console.warn(`🚨 SECURITY ALERT: Mijoz narxni manipulatsiya qilishga urindi! Mijoz yuborgan narx: ${clientTotal}, Tizim single hisoblagan narx: ${finalSecureTotal}`);
    }

    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 6).toUpperCase(),
      items: verifiedItems,
      total: finalSecureTotal,
      status: 'new',
      date: new Date().toISOString(),
      address,
      phone,
      paymentMethod,
      userName
    }; 

    await dbService.saveItem('orders', newOrder);
    await sendTelegramNotification(newOrder);
  };

  const updateOrderStatus = (orderId: string, status: Order['status']) => {
    const order = orders.find(o => o.id === orderId);
    if (order) {
        dbService.saveItem('orders', { ...order, status });
    }
  };

  return (
    <OrderContext.Provider value={{ orders, placeOrder, updateOrderStatus }}>
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error('useOrders must be used within OrderProvider');
  return context;
};

